 wanted jsonb := $six_data$[{"id":"tcf-listening-15","version":"tcf-listening-2026-11-test15-v2","title":"TCF Listening · Test 15","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La scène représente une personne assise, occupée à consulter un abonnement numérique.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un abonnement numérique à une table. D. Elle court sur un terrain de sport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un abonnement numérique à une table. D. Elle court sur un terrain de sport."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.236,"slotSeconds":33},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Un homme présente une affiche liée à médias et information.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il peint une façade extérieure. B. Il présente une affiche sur médias et information à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il peint une façade extérieure. B. Il présente une affiche sur médias et information à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.56,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Deux interlocuteurs préparent un festival de journalisme autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes préparent un festival de journalisme autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes préparent un festival de journalisme autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.209,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'illustration montre une personne portant un sac devant la rédaction locale de Bordeaux.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant la rédaction locale de Bordeaux.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant la rédaction locale de Bordeaux."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.292,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de vérification des sources ?\nA. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de vérification des sources ?"},{"voice":"female","text":"A. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos."}],"audio":"q-05.mp3","audioSeconds":19.203,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un abonnement numérique pour participer à un festival de journalisme ?\nA. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un abonnement numérique pour participer à un festival de journalisme ?"},{"voice":"female","text":"A. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail."}],"audio":"q-06.mp3","audioSeconds":20.743,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de vérification des sources ?\nA. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de vérification des sources ?"},{"voice":"female","text":"A. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat."}],"audio":"q-07.mp3","audioSeconds":17.694,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à un festival de journalisme. Est-ce possible ?\nA. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à un festival de journalisme. Est-ce possible ?"},{"voice":"female","text":"A. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau."}],"audio":"q-08.mp3","audioSeconds":21.426,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","une rubrique hebdomadaire consacrée aux décisions municipales","Un changement des modalités des réservations actuelles."],"correct":"C","explanation":"Le document permet de retenir « une rubrique hebdomadaire consacrée aux décisions municipales ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la rédaction locale de Bordeaux, à compter de lundi prochain, nous mettons en place une rubrique hebdomadaire consacrée aux décisions municipales. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la rédaction locale de Bordeaux, à compter de lundi prochain, nous mettons en place une rubrique hebdomadaire consacrée aux décisions municipales. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":23.295,"slotSeconds":39},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier de vérification des sources est reporté au lendemain.","La personne arrivera plus tard à un atelier de vérification des sources à cause d’une autre obligation.","Un autre créneau est proposé pour un atelier de vérification des sources en raison des transports.","Le rendez-vous pour un atelier de vérification des sources est avancé d’une demi-heure."],"correct":"B","explanation":"Le document permet de retenir « La personne arrivera plus tard à un atelier de vérification des sources à cause d’une autre obligation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de vérification des sources ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de vérification des sources ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":26.74,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Pour un festival de journalisme, le formulaire doit être rempli en ligne avant jeudi.","Déposer sa demande pour un festival de journalisme à l’accueil le jour même.","Réserver sa place pour un festival de journalisme par téléphone avant jeudi.","Envoyer le formulaire de un festival de journalisme par courriel avant vendredi."],"correct":"A","explanation":"Le document permet de retenir « Pour un festival de journalisme, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Médias et information » aura lieu dans la rédaction locale de Bordeaux. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Médias et information » aura lieu dans la rédaction locale de Bordeaux. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.004,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Présenter une pièce d’identité à l’accueil pour accéder à un atelier de vérification des sources.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de vérification des sources.","Demander une confirmation écrite après la fin de un atelier de vérification des sources.","Présenter le message de confirmation pour un atelier de vérification des sources à l’accueil."],"correct":"D","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier de vérification des sources à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de vérification des sources, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de vérification des sources, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.885,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de vérification des sources est reportée au lendemain à la même heure.","La séance de un atelier de vérification des sources change de salle mais garde le même horaire.","La séance prévue pour un atelier de vérification des sources commence une heure plus tard.","La séance de un atelier de vérification des sources commence une heure plus tôt que prévu."],"correct":"C","explanation":"Le document permet de retenir « La séance prévue pour un atelier de vérification des sources commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de vérification des sources. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de vérification des sources. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.796,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Garder un atelier de vérification des sources mais renoncer à fournir la démonstration prévue.","Conserver un atelier de vérification des sources et envoyer ensuite la démonstration manquante.","Maintenir un atelier de vérification des sources avec une démonstration réalisée sans le matériel.","Reporter un atelier de vérification des sources jusqu’à ce que le matériel soit disponible."],"correct":"B","explanation":"Le document permet de retenir « Conserver un atelier de vérification des sources et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de vérification des sources n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de vérification des sources n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.101,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans la rédaction locale de Bordeaux, la mesure a été suspendue faute de participants.","Dans la rédaction locale de Bordeaux, les difficultés ont été réglées avant le lancement.","Dans la rédaction locale de Bordeaux, l’initiative est désormais réservée aux habitués."],"correct":"A","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la rédaction locale de Bordeaux : une rubrique hebdomadaire consacrée aux décisions municipales. Le dispositif vise à répondre à une difficulté bien connue : les informations circulent plus rapidement que leur vérification. Plusieurs représentants soulignent toutefois que les petites rédactions manquent de temps pour certaines vérifications. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la rédaction locale de Bordeaux : une rubrique hebdomadaire consacrée aux décisions municipales. Le dispositif vise à répondre à une difficulté bien connue : les informations circulent plus rapidement que leur vérification. Plusieurs représentants soulignent toutefois que les petites rédactions manquent de temps pour certaines vérifications. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":34.118,"slotSeconds":50},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Réserver les permanences de le journal de proximité aux inscriptions du matin.","Répartir les permanences de le journal de proximité entre deux lieux différents.","Avancer les horaires de le journal de proximité en supprimant le relais du soir.","Répartir les permanences du journal de proximité pour maintenir l’accueil continu."],"correct":"D","explanation":"Le document permet de retenir « Répartir les permanences du journal de proximité pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le journal de proximité.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le journal de proximité."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.062,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les employés chargés d’accueillir et d’orienter les visiteurs de la rédaction locale de Bordeaux.","Les visiteurs ayant déjà terminé leurs démarches dans la rédaction locale de Bordeaux.","Les visiteurs de la rédaction locale de Bordeaux qui peinent à accéder au service ordinaire.","Les personnes qui fréquentent régulièrement les ateliers de la rédaction locale de Bordeaux."],"correct":"C","explanation":"Le document permet de retenir « Les visiteurs de la rédaction locale de Bordeaux qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la rédaction locale de Bordeaux. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les informations circulent plus rapidement que leur vérification. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la rédaction locale de Bordeaux. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les informations circulent plus rapidement que leur vérification. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":29.53,"slotSeconds":46},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle ne peut se rendre à un festival de journalisme à cause d’un retard de transport.","Elle travaille encore vendredi à seize heures, au moment d’un festival de journalisme.","Elle souhaite déplacer un festival de journalisme à cause d’un changement de salle.","Elle demande un autre horaire pour un festival de journalisme afin d’accompagner un proche."],"correct":"B","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’un festival de journalisme ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour un festival de journalisme. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour un festival de journalisme. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.881,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Permettre à chaque participant de poser ses questions et d’échanger.","Adapter le nombre de places de un festival de journalisme à la taille de la salle.","Répartir les participants de un festival de journalisme selon leur expérience.","Réduire le groupe de un festival de journalisme pour utiliser moins de matériel."],"correct":"A","explanation":"Le document permet de retenir « Permettre à chaque participant de poser ses questions et d’échanger ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour un festival de journalisme, des visites en petits groupes seront proposées dans la rédaction locale de Bordeaux. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour un festival de journalisme, des visites en petits groupes seront proposées dans la rédaction locale de Bordeaux. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.155,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués.","La visiteuse souhaite des précisions sur l'indépendance éditoriale face aux financeurs."],"correct":"D","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur l'indépendance éditoriale face aux financeurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte l'indépendance éditoriale face aux financeurs. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte l'indépendance éditoriale face aux financeurs. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.287,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Adapter les tâches des bénévoles aux compétences requises pour un festival de journalisme.","Prévoir le matériel nécessaire selon les inscriptions à un festival de journalisme.","Répartir les bénévoles d’un festival de journalisme selon les créneaux où ils sont libres.","Définir les activités prioritaires selon le public attendu pour un festival de journalisme."],"correct":"C","explanation":"Le document permet de retenir « Répartir les bénévoles d’un festival de journalisme selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la rédaction locale de Bordeaux, pour préparer un festival de journalisme, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la rédaction locale de Bordeaux, pour préparer un festival de journalisme, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.835,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les nouveaux contacts professionnels pris pendant un atelier de vérification des sources.","Les relations de confiance établies pendant un atelier de vérification des sources avec les participants.","La meilleure organisation des activités obtenue grâce à un atelier de vérification des sources.","Les connaissances pratiques acquises au cours de un atelier de vérification des sources."],"correct":"B","explanation":"Le document permet de retenir « Les relations de confiance établies pendant un atelier de vérification des sources avec les participants ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de vérification des sources. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les informations circulent plus rapidement que leur vérification. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de vérification des sources. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les informations circulent plus rapidement que leur vérification. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":44.985,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Tester des procédures de confirmation et des explications sur les corrections, consulter les usagers puis publier un bilan.","Expérimenter des procédures de confirmation et des explications sur les corrections mais ne publier aucun retour des participants.","Mettre en place des procédures de confirmation et des explications sur les corrections partout avant de mesurer les résultats.","Consulter les habitants sur des procédures de confirmation et des explications sur les corrections sans mener d’essai concret."],"correct":"A","explanation":"Le document permet de retenir « Tester des procédures de confirmation et des explications sur les corrections, consulter les usagers puis publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Médias et information ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des procédures de confirmation et des explications sur les corrections.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les informations circulent plus rapidement que leur vérification.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Médias et information »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des procédures de confirmation et des explications sur les corrections."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les informations circulent plus rapidement que leur vérification."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":55.204,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le journal de proximité donne peu de place aux nouveaux inscrits.","L’étude de le journal de proximité comprend surtout des personnes en attente.","L’étude de le journal de proximité s’appuie principalement sur les réponses des agents.","L’étude sur le journal de proximité n’a presque pas touché ceux qui ont abandonné."],"correct":"D","explanation":"Le document permet de retenir « L’étude sur le journal de proximité n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le journal de proximité. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les informations circulent plus rapidement que leur vérification. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le journal de proximité. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les informations circulent plus rapidement que leur vérification. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":50.922,"slotSeconds":67},{"number":25,"kind":"television-report","question":"Quelle difficulté les rédactions doivent-elles concilier ?","options":["Maintenir les effectifs en supprimant les enquêtes difficiles à vérifier.","Financer les enquêtes grâce aux annonceurs sans définir de garde-fous.","Renforcer la vérification sans compromettre l’indépendance de la rédaction.","Accélérer la diffusion des informations en reportant leur vérification."],"correct":"C","explanation":"Les responsables souhaitent financer des enquêtes et maintenir des équipes locales, mais ils doivent préserver l’indépendance éditoriale face aux financeurs, malgré les contraintes de temps. Les autres réponses abandonnent la vérification, acceptent la dépendance financière ou introduisent une stratégie absente du reportage.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la rédaction locale de Bordeaux, une initiative propose des procédures de confirmation et des explications sur les corrections. Les responsables espèrent ainsi répondre à une difficulté bien connue : les informations circulent plus rapidement que leur vérification.\nNous soutenons l’objectif général, mais il faut prendre en compte l'indépendance éditoriale face aux financeurs. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment vouloir financer des enquêtes approfondies tout en maintenant des équipes locales. Pourtant, les petites rédactions manquent de temps pour certaines vérifications. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle difficulté les rédactions doivent-elles concilier ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la rédaction locale de Bordeaux, une initiative propose des procédures de confirmation et des explications sur les corrections. Les responsables espèrent ainsi répondre à une difficulté bien connue : les informations circulent plus rapidement que leur vérification."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte l'indépendance éditoriale face aux financeurs. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment vouloir financer des enquêtes approfondies tout en maintenant des équipes locales. Pourtant, les petites rédactions manquent de temps pour certaines vérifications. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle difficulté les rédactions doivent-elles concilier ?"}],"slotSeconds":73,"audio":"q-25.mp3","audioSeconds":54.311},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["L’équipe souhaite interrompre une rubrique hebdomadaire consacrée aux décisions municipales dès la fin des premiers essais.","La nouvelle mesure, une rubrique hebdomadaire consacrée aux décisions municipales, doit encore être évaluée sur la durée.","Le projet de une rubrique hebdomadaire consacrée aux décisions municipales est annoncé mais n’a pas encore été lancé.","Les résultats de une rubrique hebdomadaire consacrée aux décisions municipales concernent uniquement les coûts de gestion."],"correct":"B","explanation":"Le document permet de retenir « La nouvelle mesure, une rubrique hebdomadaire consacrée aux décisions municipales, doit encore être évaluée sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une rubrique hebdomadaire consacrée aux décisions municipales. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les petites rédactions manquent de temps pour certaines vérifications. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : le taux de corrections et la confiance du public au fil du temps. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une rubrique hebdomadaire consacrée aux décisions municipales. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les petites rédactions manquent de temps pour certaines vérifications. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : le taux de corrections et la confiance du public au fil du temps. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":50.301,"slotSeconds":67},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Ouvrir plus tôt sans priver les usagers des permanences du soir.","Ouvrir le journal de proximité plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de le journal de proximité malgré les demandes du matin.","Réserver les créneaux matinaux de le journal de proximité aux seuls abonnés."],"correct":"A","explanation":"Le document permet de retenir « Ouvrir plus tôt sans priver les usagers des permanences du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le journal de proximité ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le journal de proximité ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.724,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Adapter les équipements de une plateforme de signalement des erreurs après consultation des équipes.","Tester une plateforme de signalement des erreurs sur un seul site avant de l’ouvrir à tous.","Préparer le budget de une plateforme de signalement des erreurs avant de calculer son entretien.","Concevoir une plateforme de signalement des erreurs avant de comprendre les besoins réels des utilisateurs."],"correct":"D","explanation":"Le document permet de retenir « Concevoir une plateforme de signalement des erreurs avant de comprendre les besoins réels des utilisateurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de une plateforme de signalement des erreurs a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'indépendance éditoriale face aux financeurs est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une plateforme de signalement des erreurs a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'indépendance éditoriale face aux financeurs est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":50.471,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de le taux de corrections et la confiance du public au fil du temps ; l’autre mesure la fréquentation.","L’un veut mesurer le taux de corrections et la confiance du public au fil du temps ; l’autre demande des récits.","L’un défend les entretiens, l’autre réclame surtout les données financières."],"correct":"C","explanation":"Le document permet de retenir « L’un veut mesurer le taux de corrections et la confiance du public au fil du temps ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Médias et information ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : le taux de corrections et la confiance du public au fil du temps et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les informations circulent plus rapidement que leur vérification. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Médias et information »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : le taux de corrections et la confiance du public au fil du temps et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les informations circulent plus rapidement que leur vérification. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":51.441,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Rénover le lieu de un atelier de vérification des sources sans changer l’usage actuel des espaces.","Conserver l’identité du lieu accueillant un atelier de vérification des sources tout en permettant de nouveaux usages.","Conserver le bâtiment de un atelier de vérification des sources uniquement pour ses activités passées.","Moderniser les salles de un atelier de vérification des sources en effaçant les anciennes traces."],"correct":"B","explanation":"Le document permet de retenir « Conserver l’identité du lieu accueillant un atelier de vérification des sources tout en permettant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de vérification des sources, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de vérification des sources, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.961,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Confronter les prévisions d’un modèle aux observations réelles.","Vérifier seulement si le modèle retrouve les données de départ.","Réviser les hypothèses avant toute observation de terrain.","Comparer les prévisions de plusieurs modèles entre elles."],"correct":"A","explanation":"Le document permet de retenir « Confronter les prévisions d’un modèle aux observations réelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, le taux de corrections et la confiance du public au fil du temps. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les informations circulent plus rapidement que leur vérification. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, le taux de corrections et la confiance du public au fil du temps. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les informations circulent plus rapidement que leur vérification. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":57.022,"slotSeconds":74},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le journal de proximité, publier un chiffre précis sans détailler ses limites.","Pour le journal de proximité, annoncer une moyenne sans préciser les hypothèses retenues.","Pour le journal de proximité, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le journal de proximité, présenter les hypothèses et les incertitudes des prévisions."],"correct":"D","explanation":"Le document permet de retenir « Pour le journal de proximité, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le journal de proximité, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le journal de proximité, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":51.706,"slotSeconds":68},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La fréquentation de la rédaction locale de Bordeaux varie trop selon les saisons.","Les chiffres de la rédaction locale de Bordeaux ne tiennent pas compte du prix des activités.","La hausse des visites ne démontre pas un bénéfice durable du projet.","La hausse des visites à la rédaction locale de Bordeaux vient surtout des horaires étendus."],"correct":"C","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la rédaction locale de Bordeaux, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une rubrique hebdomadaire consacrée aux décisions municipales. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer le taux de corrections et la confiance du public au fil du temps ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la rédaction locale de Bordeaux, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une rubrique hebdomadaire consacrée aux décisions municipales. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer le taux de corrections et la confiance du public au fil du temps ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":50.498,"slotSeconds":68},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Maintenir une aide humaine à le journal de proximité pendant le seul lancement.","Faire tester le journal de proximité par différents publics et maintenir une aide humaine.","Évaluer le journal de proximité auprès de tous puis supprimer l’accueil individuel.","Faire tester le journal de proximité uniquement par les usagers réguliers."],"correct":"B","explanation":"Le document permet de retenir « Faire tester le journal de proximité par différents publics et maintenir une aide humaine ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la rédaction locale de Bordeaux.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'indépendance éditoriale face aux financeurs.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la rédaction locale de Bordeaux."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'indépendance éditoriale face aux financeurs."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":54.032,"slotSeconds":72},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les résultats annoncés suffisent, même si les usages réels diffèrent.","Les conditions de terrain de le studio radio influencent les résultats observés.","La performance du dispositif de le studio radio exige un entretien régulier.","Les usages quotidiens du matériel de le studio radio peuvent changer ses effets."],"correct":"A","explanation":"Le document permet de retenir « Les résultats annoncés suffisent, même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le studio radio affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le studio radio affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":49.959,"slotSeconds":67},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Assurer une présence régulière aux séances de un atelier de vérification des sources sans échanger.","Répartir les rôles de un atelier de vérification des sources entre des participants désignés à l’avance.","Évaluer le lien créé à un atelier de vérification des sources uniquement par le nombre de présences.","Permettre une participation volontaire et réciproque à un atelier de vérification des sources."],"correct":"D","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de vérification des sources ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de vérification des sources réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'indépendance éditoriale face aux financeurs. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de vérification des sources réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'indépendance éditoriale face aux financeurs. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.068,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Classer les témoignages de le journal de proximité selon l’ancienneté de leurs auteurs.","Comparer les récits de le journal de proximité sans consulter les archives disponibles.","Comparer les récits concernant le journal de proximité aux faits vérifiables.","Conserver les récits de le journal de proximité qui concordent avec la majorité."],"correct":"C","explanation":"Le document permet de retenir « Comparer les récits concernant le journal de proximité aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le journal de proximité, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le journal de proximité, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":51.921,"slotSeconds":69},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La croissance de une rubrique hebdomadaire consacrée aux décisions municipales augmente le budget sans effet sur les usagers.","Une initiative comme une rubrique hebdomadaire consacrée aux décisions municipales peut devenir victime de son succès et fragiliser les usagers.","Le succès de une rubrique hebdomadaire consacrée aux décisions municipales réduit les demandes des services voisins.","La fréquentation de une rubrique hebdomadaire consacrée aux décisions municipales ralentit la promotion du dispositif."],"correct":"B","explanation":"Le document permet de retenir « Une initiative comme une rubrique hebdomadaire consacrée aux décisions municipales peut devenir victime de son succès et fragiliser les usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Médias et information ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une rubrique hebdomadaire consacrée aux décisions municipales peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les informations circulent plus rapidement que leur vérification. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'indépendance éditoriale face aux financeurs. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Médias et information ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une rubrique hebdomadaire consacrée aux décisions municipales peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les informations circulent plus rapidement que leur vérification. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'indépendance éditoriale face aux financeurs. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.793,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Stabiliser les moyens et suivre le taux de corrections et la confiance du public au fil du temps dans la durée.","Suivre le taux de corrections et la confiance du public au fil du temps en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer le taux de corrections et la confiance du public au fil du temps.","Étendre le service en privilégiant seulement les premiers résultats de le taux de corrections et la confiance du public au fil du temps."],"correct":"A","explanation":"Le document permet de retenir « Stabiliser les moyens et suivre le taux de corrections et la confiance du public au fil du temps dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le journal de proximité, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les petites rédactions manquent de temps pour certaines vérifications. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre le taux de corrections et la confiance du public au fil du temps. L’idée n’est pas d’abandonner l’ambition de départ : financer des enquêtes approfondies et garder des équipes locales. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le journal de proximité, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les petites rédactions manquent de temps pour certaines vérifications. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre le taux de corrections et la confiance du public au fil du temps. L’idée n’est pas d’abandonner l’ambition de départ : financer des enquêtes approfondies et garder des équipes locales. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.658,"slotSeconds":81}]},{"id":"tcf-listening-16","version":"tcf-listening-2026-11-test16-v2","title":"TCF Listening · Test 16","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La scène représente une personne assise, occupée à consulter un calendrier de garde partagée.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un calendrier de garde partagée à une table.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un calendrier de garde partagée à une table."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.454,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Un homme présente une affiche liée à familles et vie sociale.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur familles et vie sociale à un groupe. D. Il prépare un repas dans la cuisine.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur familles et vie sociale à un groupe. D. Il prépare un repas dans la cuisine."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.537,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Deux interlocuteurs préparent une fête intergénérationnelle autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Trois personnes font de la randonnée. B. Deux personnes préparent une fête intergénérationnelle autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Trois personnes font de la randonnée. B. Deux personnes préparent une fête intergénérationnelle autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.758,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'illustration montre une personne portant un sac devant la maison des familles d'Orléans.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme porte un sac devant la maison des familles d'Orléans. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme porte un sac devant la maison des familles d'Orléans. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":17.746,"slotSeconds":33},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de jeux entre générations ?\nA. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de jeux entre générations ?"},{"voice":"female","text":"A. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil."}],"audio":"q-05.mp3","audioSeconds":19.737,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un calendrier de garde partagée pour participer à une fête intergénérationnelle ?\nA. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un calendrier de garde partagée pour participer à une fête intergénérationnelle ?"},{"voice":"female","text":"A. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche."}],"audio":"q-06.mp3","audioSeconds":20.138,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de jeux entre générations ?\nA. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de jeux entre générations ?"},{"voice":"female","text":"A. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr."}],"audio":"q-07.mp3","audioSeconds":17.636,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une fête intergénérationnelle. Est-ce possible ?\nA. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une fête intergénérationnelle. Est-ce possible ?"},{"voice":"female","text":"A. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue."}],"audio":"q-08.mp3","audioSeconds":21.161,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées.","un accueil supplémentaire pour les parents le vendredi"],"correct":"D","explanation":"Le document permet de retenir « un accueil supplémentaire pour les parents le vendredi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la maison des familles d'Orléans, à compter de lundi prochain, nous mettons en place un accueil supplémentaire pour les parents le vendredi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la maison des familles d'Orléans, à compter de lundi prochain, nous mettons en place un accueil supplémentaire pour les parents le vendredi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.844,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Un autre créneau est proposé pour un atelier de jeux entre générations en raison des transports.","Le rendez-vous pour un atelier de jeux entre générations est avancé d’une demi-heure.","Le rendez-vous d’un atelier de jeux entre générations est repoussé à cause d’une réunion prolongée.","Le rendez-vous pour un atelier de jeux entre générations est reporté au lendemain."],"correct":"C","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de jeux entre générations est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de jeux entre générations ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de jeux entre générations ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.361,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Réserver sa place pour une fête intergénérationnelle par téléphone avant jeudi.","Remplir en ligne le formulaire d’inscription pour une fête intergénérationnelle avant jeudi.","Envoyer le formulaire de une fête intergénérationnelle par courriel avant vendredi.","Déposer sa demande pour une fête intergénérationnelle à l’accueil le jour même."],"correct":"B","explanation":"Le document permet de retenir « Remplir en ligne le formulaire d’inscription pour une fête intergénérationnelle avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Familles et vie sociale » aura lieu dans la maison des familles d'Orléans. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Familles et vie sociale » aura lieu dans la maison des familles d'Orléans. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.073,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Montrer le courriel de confirmation à l’accueil pour retrouver son inscription.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de jeux entre générations.","Demander une confirmation écrite après la fin de un atelier de jeux entre générations.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier de jeux entre générations."],"correct":"A","explanation":"Le document permet de retenir « Montrer le courriel de confirmation à l’accueil pour retrouver son inscription ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de jeux entre générations, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de jeux entre générations, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.013,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de jeux entre générations change de salle mais garde le même horaire.","La séance de un atelier de jeux entre générations commence une heure plus tôt que prévu.","La séance de un atelier de jeux entre générations est reportée au lendemain à la même heure.","La séance prévue pour un atelier de jeux entre générations commence une heure plus tard."],"correct":"D","explanation":"Le document permet de retenir « La séance prévue pour un atelier de jeux entre générations commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de jeux entre générations. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de jeux entre générations. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.307,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Maintenir un atelier de jeux entre générations avec une démonstration réalisée sans le matériel.","Reporter un atelier de jeux entre générations jusqu’à ce que le matériel soit disponible.","Conserver un atelier de jeux entre générations et envoyer ensuite la démonstration manquante.","Garder un atelier de jeux entre générations mais renoncer à fournir la démonstration prévue."],"correct":"C","explanation":"Le document permet de retenir « Conserver un atelier de jeux entre générations et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de jeux entre générations n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de jeux entre générations n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.287,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans la maison des familles d'Orléans, les difficultés ont été réglées avant le lancement.","La mesure présentée à la maison des familles d'Orléans répond au besoin sans lever toutes les difficultés.","Dans la maison des familles d'Orléans, l’initiative est désormais réservée aux habitués.","Dans la maison des familles d'Orléans, la mesure a été suspendue faute de participants."],"correct":"B","explanation":"Le document permet de retenir « La mesure présentée à la maison des familles d'Orléans répond au besoin sans lever toutes les difficultés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la maison des familles d'Orléans : un accueil supplémentaire pour les parents le vendredi. Le dispositif vise à répondre à une difficulté bien connue : les horaires de travail et la garde des enfants compliquent la participation. Plusieurs représentants soulignent toutefois que les places d'accueil du mercredi sont déjà très demandées. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la maison des familles d'Orléans : un accueil supplémentaire pour les parents le vendredi. Le dispositif vise à répondre à une difficulté bien connue : les horaires de travail et la garde des enfants compliquent la participation. Plusieurs représentants soulignent toutefois que les places d'accueil du mercredi sont déjà très demandées. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.607,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Maintenir un accueil sans interruption malgré les changements de service.","Répartir les permanences de le service d'entraide entre voisins entre deux lieux différents.","Avancer les horaires de le service d'entraide entre voisins en supprimant le relais du soir.","Réserver les permanences de le service d'entraide entre voisins aux inscriptions du matin."],"correct":"A","explanation":"Le document permet de retenir « Maintenir un accueil sans interruption malgré les changements de service ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le service d'entraide entre voisins.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le service d'entraide entre voisins."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.179,"slotSeconds":42},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les visiteurs ayant déjà terminé leurs démarches dans la maison des familles d'Orléans.","Les personnes qui fréquentent régulièrement les ateliers de la maison des familles d'Orléans.","Les employés chargés d’accueillir et d’orienter les visiteurs de la maison des familles d'Orléans.","Les visiteurs de la maison des familles d'Orléans qui peinent à accéder au service ordinaire."],"correct":"D","explanation":"Le document permet de retenir « Les visiteurs de la maison des familles d'Orléans qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la maison des familles d'Orléans. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les horaires de travail et la garde des enfants compliquent la participation. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la maison des familles d'Orléans. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les horaires de travail et la garde des enfants compliquent la participation. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.134,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle souhaite déplacer une fête intergénérationnelle à cause d’un changement de salle.","Elle demande un autre horaire pour une fête intergénérationnelle afin d’accompagner un proche.","Elle travaille encore vendredi à seize heures, au moment d’une fête intergénérationnelle.","Elle ne peut se rendre à une fête intergénérationnelle à cause d’un retard de transport."],"correct":"C","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une fête intergénérationnelle ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une fête intergénérationnelle. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une fête intergénérationnelle. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.556,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Répartir les participants de une fête intergénérationnelle selon leur expérience.","Limiter le groupe pendant une fête intergénérationnelle afin que chacun puisse poser des questions.","Réduire le groupe de une fête intergénérationnelle pour utiliser moins de matériel.","Adapter le nombre de places de une fête intergénérationnelle à la taille de la salle."],"correct":"B","explanation":"Le document permet de retenir « Limiter le groupe pendant une fête intergénérationnelle afin que chacun puisse poser des questions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une fête intergénérationnelle, des visites en petits groupes seront proposées dans la maison des familles d'Orléans. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une fête intergénérationnelle, des visites en petits groupes seront proposées dans la maison des familles d'Orléans. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.364,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["La visiteuse souhaite des précisions sur le respect du choix et de l'intimité de chacun.","Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet."],"correct":"A","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur le respect du choix et de l'intimité de chacun ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte le respect du choix et de l'intimité de chacun. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte le respect du choix et de l'intimité de chacun. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.194,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Prévoir le matériel nécessaire selon les inscriptions à une fête intergénérationnelle.","Définir les activités prioritaires selon le public attendu pour une fête intergénérationnelle.","Adapter les tâches des bénévoles aux compétences requises pour une fête intergénérationnelle.","Répartir les bénévoles d’une fête intergénérationnelle selon les créneaux où ils sont libres."],"correct":"D","explanation":"Le document permet de retenir « Répartir les bénévoles d’une fête intergénérationnelle selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la maison des familles d'Orléans, pour préparer une fête intergénérationnelle, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la maison des familles d'Orléans, pour préparer une fête intergénérationnelle, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.751,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["La meilleure organisation des activités obtenue grâce à un atelier de jeux entre générations.","Les connaissances pratiques acquises au cours de un atelier de jeux entre générations.","Les relations de confiance créées autour d’un atelier de jeux entre générations.","Les nouveaux contacts professionnels pris pendant un atelier de jeux entre générations."],"correct":"C","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de jeux entre générations ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de jeux entre générations. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les horaires de travail et la garde des enfants compliquent la participation. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de jeux entre générations. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les horaires de travail et la garde des enfants compliquent la participation. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.873,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Mettre en place des activités accessibles et des horaires décidés avec les familles partout avant de mesurer les résultats.","Expérimenter des activités accessibles et des horaires décidés avec les familles, recueillir les avis et publier un bilan.","Consulter les habitants sur des activités accessibles et des horaires décidés avec les familles sans mener d’essai concret.","Expérimenter des activités accessibles et des horaires décidés avec les familles mais ne publier aucun retour des participants."],"correct":"B","explanation":"Le document permet de retenir « Expérimenter des activités accessibles et des horaires décidés avec les familles, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Familles et vie sociale ».\nNous avons discuté de des activités accessibles et des horaires décidés avec les familles, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan.\nLes usagers craignent surtout le respect du choix et de l'intimité de chacun. Une application immédiate, sans consultation, risquerait de perdre leur confiance.\nAlors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Familles et vie sociale »."},{"voice":"male","text":"Nous avons discuté de des activités accessibles et des horaires décidés avec les familles, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan."},{"voice":"female","text":"Les usagers craignent surtout le respect du choix et de l'intimité de chacun. Une application immédiate, sans consultation, risquerait de perdre leur confiance."},{"voice":"male","text":"Alors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":57.596,"slotSeconds":74},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les usagers qui ont abandonné le service d'entraide entre voisins sont peu représentés.","L’étude de le service d'entraide entre voisins comprend surtout des personnes en attente.","L’étude de le service d'entraide entre voisins s’appuie principalement sur les réponses des agents.","L’étude de le service d'entraide entre voisins donne peu de place aux nouveaux inscrits."],"correct":"A","explanation":"Le document permet de retenir « Les usagers qui ont abandonné le service d'entraide entre voisins sont peu représentés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le service d'entraide entre voisins. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les horaires de travail et la garde des enfants compliquent la participation. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le service d'entraide entre voisins. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les horaires de travail et la garde des enfants compliquent la participation. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.14,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle difficulté l’initiative doit-elle prendre en compte ?","options":["Étendre les activités sans consulter les familles sur les horaires.","Confier l’ensemble des permanences aux seuls bénévoles disponibles.","Limiter les rencontres aux familles pouvant venir en semaine.","Adapter l’accueil aux familles sans épuiser les personnes qui l’animent."],"correct":"D","explanation":"Le reportage évoque des activités accessibles et des horaires décidés avec les familles, mais souligne la forte demande du mercredi et la fatigue possible des bénévoles. Il ne recommande ni l’exclusion des familles ni le transfert complet de l’accueil aux bénévoles.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la maison des familles d'Orléans, une initiative propose des activités accessibles et des horaires décidés avec les familles. Les responsables espèrent ainsi répondre à une difficulté bien connue : les horaires de travail et la garde des enfants compliquent la participation.\nNous soutenons l’objectif général, mais il faut prendre en compte le respect du choix et de l'intimité de chacun. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils souhaitent soutenir les aidants sans accroître l’épuisement des bénévoles. Pourtant, les places d'accueil du mercredi sont déjà très demandées. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle difficulté l’initiative doit-elle prendre en compte ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la maison des familles d'Orléans, une initiative propose des activités accessibles et des horaires décidés avec les familles. Les responsables espèrent ainsi répondre à une difficulté bien connue : les horaires de travail et la garde des enfants compliquent la participation."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte le respect du choix et de l'intimité de chacun. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils souhaitent soutenir les aidants sans accroître l’épuisement des bénévoles. Pourtant, les places d'accueil du mercredi sont déjà très demandées. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle difficulté l’initiative doit-elle prendre en compte ?"}],"slotSeconds":73,"audio":"q-25.mp3","audioSeconds":53.188},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Le projet de un accueil supplémentaire pour les parents le vendredi est annoncé mais n’a pas encore été lancé.","Les résultats de un accueil supplémentaire pour les parents le vendredi concernent uniquement les coûts de gestion.","Les premiers effets d’un accueil supplémentaire pour les parents le vendredi doivent être vérifiés dans la durée.","L’équipe souhaite interrompre un accueil supplémentaire pour les parents le vendredi dès la fin des premiers essais."],"correct":"C","explanation":"Le document permet de retenir « Les premiers effets d’un accueil supplémentaire pour les parents le vendredi doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé un accueil supplémentaire pour les parents le vendredi. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les places d'accueil du mercredi sont déjà très demandées. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la qualité et la durée des relations créées. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé un accueil supplémentaire pour les parents le vendredi. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les places d'accueil du mercredi sont déjà très demandées. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la qualité et la durée des relations créées. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.293,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Conserver les horaires de le service d'entraide entre voisins malgré les demandes du matin.","Réorganiser les horaires du service d'entraide entre voisins sans supprimer les créneaux du soir.","Réserver les créneaux matinaux de le service d'entraide entre voisins aux seuls abonnés.","Ouvrir le service d'entraide entre voisins plus tôt en supprimant les créneaux tardifs."],"correct":"B","explanation":"Le document permet de retenir « Réorganiser les horaires du service d'entraide entre voisins sans supprimer les créneaux du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le service d'entraide entre voisins ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le service d'entraide entre voisins ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.12,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Tester une salle de repos familiale sur un seul site avant de l’ouvrir à tous.","Préparer le budget de une salle de repos familiale avant de calculer son entretien.","Adapter les équipements de une salle de repos familiale après consultation des équipes."],"correct":"A","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de une salle de repos familiale a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le respect du choix et de l'intimité de chacun est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une salle de repos familiale a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le respect du choix et de l'intimité de chacun est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":48.606,"slotSeconds":65},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut comparer les coûts de la qualité et la durée des relations créées ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut mesurer la qualité et la durée des relations créées ; l’autre demande des récits."],"correct":"D","explanation":"Le document permet de retenir « L’un veut mesurer la qualité et la durée des relations créées ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Familles et vie sociale ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la qualité et la durée des relations créées et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les horaires de travail et la garde des enfants compliquent la participation. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Familles et vie sociale »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la qualité et la durée des relations créées et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les horaires de travail et la garde des enfants compliquent la participation. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":51.186,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Conserver le bâtiment de un atelier de jeux entre générations uniquement pour ses activités passées.","Moderniser les salles de un atelier de jeux entre générations en effaçant les anciennes traces.","Préserver l’histoire du lieu d’un atelier de jeux entre générations tout en y proposant de nouveaux usages.","Rénover le lieu de un atelier de jeux entre générations sans changer l’usage actuel des espaces."],"correct":"C","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de jeux entre générations tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de jeux entre générations, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de jeux entre générations, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.758,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Établir une cause unique à partir de deux changements simultanés.","Ne pas confondre une corrélation statistique et une cause démontrée.","Comparer la force d’une corrélation dans plusieurs échantillons.","Déduire un effet causal lorsque deux tendances se répètent."],"correct":"B","explanation":"Le document permet de retenir « Ne pas confondre une corrélation statistique et une cause démontrée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la qualité et la durée des relations créées. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les horaires de travail et la garde des enfants compliquent la participation. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la qualité et la durée des relations créées. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les horaires de travail et la garde des enfants compliquent la participation. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":50.683,"slotSeconds":68},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le service d'entraide entre voisins, présenter les hypothèses et les incertitudes des prévisions.","Pour le service d'entraide entre voisins, annoncer une moyenne sans préciser les hypothèses retenues.","Pour le service d'entraide entre voisins, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le service d'entraide entre voisins, publier un chiffre précis sans détailler ses limites."],"correct":"A","explanation":"Le document permet de retenir « Pour le service d'entraide entre voisins, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le service d'entraide entre voisins, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le service d'entraide entre voisins, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.652,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Les chiffres de la maison des familles d'Orléans ne tiennent pas compte du prix des activités.","La hausse des visites à la maison des familles d'Orléans vient surtout des horaires étendus.","La fréquentation de la maison des familles d'Orléans varie trop selon les saisons.","La hausse des visites ne démontre pas un bénéfice durable du projet."],"correct":"D","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la maison des familles d'Orléans, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un accueil supplémentaire pour les parents le vendredi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la qualité et la durée des relations créées ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la maison des familles d'Orléans, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un accueil supplémentaire pour les parents le vendredi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la qualité et la durée des relations créées ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.06,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Évaluer le service d'entraide entre voisins auprès de tous puis supprimer l’accueil individuel.","Faire tester le service d'entraide entre voisins uniquement par les usagers réguliers.","Faire tester le service d'entraide entre voisins par divers publics, avec une aide humaine conservée.","Maintenir une aide humaine à le service d'entraide entre voisins pendant le seul lancement."],"correct":"C","explanation":"Le document permet de retenir « Faire tester le service d'entraide entre voisins par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la maison des familles d'Orléans.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le respect du choix et de l'intimité de chacun.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la maison des familles d'Orléans."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le respect du choix et de l'intimité de chacun."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.974,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["La performance du dispositif de le centre de quartier exige un entretien régulier.","Une technologie installée dans le centre de quartier garantit un bon résultat sans tenir compte des usages.","Les usages quotidiens du matériel de le centre de quartier peuvent changer ses effets.","Les conditions de terrain de le centre de quartier influencent les résultats observés."],"correct":"B","explanation":"Le document permet de retenir « Une technologie installée dans le centre de quartier garantit un bon résultat sans tenir compte des usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le centre de quartier affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le centre de quartier affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.347,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Permettre une participation volontaire et réciproque à un atelier de jeux entre générations.","Répartir les rôles de un atelier de jeux entre générations entre des participants désignés à l’avance.","Évaluer le lien créé à un atelier de jeux entre générations uniquement par le nombre de présences.","Assurer une présence régulière aux séances de un atelier de jeux entre générations sans échanger."],"correct":"A","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de jeux entre générations ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de jeux entre générations réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le respect du choix et de l'intimité de chacun. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de jeux entre générations réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le respect du choix et de l'intimité de chacun. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.411,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits de le service d'entraide entre voisins sans consulter les archives disponibles.","Conserver les récits de le service d'entraide entre voisins qui concordent avec la majorité.","Classer les témoignages de le service d'entraide entre voisins selon l’ancienneté de leurs auteurs.","Comparer les récits concernant le service d'entraide entre voisins aux faits vérifiables."],"correct":"D","explanation":"Le document permet de retenir « Comparer les récits concernant le service d'entraide entre voisins aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le service d'entraide entre voisins, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le service d'entraide entre voisins, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":54.684,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès de un accueil supplémentaire pour les parents le vendredi réduit les demandes des services voisins.","La fréquentation de un accueil supplémentaire pour les parents le vendredi ralentit la promotion du dispositif.","Le succès d’un accueil supplémentaire pour les parents le vendredi peut créer des difficultés aux usagers.","La croissance de un accueil supplémentaire pour les parents le vendredi augmente le budget sans effet sur les usagers."],"correct":"C","explanation":"Le document permet de retenir « Le succès d’un accueil supplémentaire pour les parents le vendredi peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Familles et vie sociale ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accueil supplémentaire pour les parents le vendredi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les horaires de travail et la garde des enfants compliquent la participation. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le respect du choix et de l'intimité de chacun. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Familles et vie sociale ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accueil supplémentaire pour les parents le vendredi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les horaires de travail et la garde des enfants compliquent la participation. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le respect du choix et de l'intimité de chacun. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.292,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Obtenir des moyens durables mais ne plus mesurer la qualité et la durée des relations créées.","Organiser des ressources durables et suivre la qualité et la durée des relations créées pour poursuivre le service d'entraide entre voisins.","Étendre le service en privilégiant seulement les premiers résultats de la qualité et la durée des relations créées.","Suivre la qualité et la durée des relations créées en comptant sur les bénévoles actuels."],"correct":"B","explanation":"Le document permet de retenir « Organiser des ressources durables et suivre la qualité et la durée des relations créées pour poursuivre le service d'entraide entre voisins ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le service d'entraide entre voisins, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les places d'accueil du mercredi sont déjà très demandées. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la qualité et la durée des relations créées. L’idée n’est pas d’abandonner l’ambition de départ : soutenir les aidants et éviter l'épuisement des bénévoles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le service d'entraide entre voisins, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les places d'accueil du mercredi sont déjà très demandées. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la qualité et la durée des relations créées. L’idée n’est pas d’abandonner l’ambition de départ : soutenir les aidants et éviter l'épuisement des bénévoles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.461,"slotSeconds":81}]},{"id":"tcf-listening-17","version":"tcf-listening-2026-11-test17-v2","title":"TCF Listening · Test 17","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La scène représente une personne assise, occupée à consulter un devis de fournisseur.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle consulte un devis de fournisseur à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle consulte un devis de fournisseur à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.027,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Un homme présente une affiche liée à économie et entreprises.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur économie et entreprises à un groupe.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur économie et entreprises à un groupe."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.583,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Deux interlocuteurs préparent une rencontre des petits entrepreneurs autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une rencontre des petits entrepreneurs autour d'une table. D. Deux personnes traversent une rivière.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une rencontre des petits entrepreneurs autour d'une table. D. Deux personnes traversent une rivière."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.803,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'illustration montre une personne portant un sac devant la chambre de commerce d'Amiens.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Des enfants jouent dans un jardin. B. Une femme porte un sac devant la chambre de commerce d'Amiens. C. Une femme nage dans une piscine. D. Un homme répare un vélo.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Des enfants jouent dans un jardin. B. Une femme porte un sac devant la chambre de commerce d'Amiens. C. Une femme nage dans une piscine. D. Un homme répare un vélo."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.083,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de gestion de trésorerie ?\nA. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de gestion de trésorerie ?"},{"voice":"female","text":"A. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie."}],"audio":"q-05.mp3","audioSeconds":19.098,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un devis de fournisseur pour participer à une rencontre des petits entrepreneurs ?\nA. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un devis de fournisseur pour participer à une rencontre des petits entrepreneurs ?"},{"voice":"female","text":"A. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place."}],"audio":"q-06.mp3","audioSeconds":20.451,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de gestion de trésorerie ?\nA. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de gestion de trésorerie ?"},{"voice":"female","text":"A. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles."}],"audio":"q-07.mp3","audioSeconds":17.258,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une rencontre des petits entrepreneurs. Est-ce possible ?\nA. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une rencontre des petits entrepreneurs. Est-ce possible ?"},{"voice":"female","text":"A. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage."}],"audio":"q-08.mp3","audioSeconds":21.658,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["un accompagnement gratuit à la transition numérique","Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits."],"correct":"A","explanation":"Le document permet de retenir « un accompagnement gratuit à la transition numérique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la chambre de commerce d'Amiens, à compter de lundi prochain, nous mettons en place un accompagnement gratuit à la transition numérique. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la chambre de commerce d'Amiens, à compter de lundi prochain, nous mettons en place un accompagnement gratuit à la transition numérique. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.879,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier de gestion de trésorerie est avancé d’une demi-heure.","Le rendez-vous pour un atelier de gestion de trésorerie est reporté au lendemain.","Un autre créneau est proposé pour un atelier de gestion de trésorerie en raison des transports.","Le rendez-vous d’un atelier de gestion de trésorerie est repoussé à cause d’une réunion prolongée."],"correct":"D","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de gestion de trésorerie est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de gestion de trésorerie ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de gestion de trésorerie ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.03,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Envoyer le formulaire de une rencontre des petits entrepreneurs par courriel avant vendredi.","Déposer sa demande pour une rencontre des petits entrepreneurs à l’accueil le jour même.","Pour une rencontre des petits entrepreneurs, le formulaire doit être rempli en ligne avant jeudi.","Réserver sa place pour une rencontre des petits entrepreneurs par téléphone avant jeudi."],"correct":"C","explanation":"Le document permet de retenir « Pour une rencontre des petits entrepreneurs, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Économie et entreprises » aura lieu dans la chambre de commerce d'Amiens. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Économie et entreprises » aura lieu dans la chambre de commerce d'Amiens. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.271,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Demander une confirmation écrite après la fin de un atelier de gestion de trésorerie.","Présenter le message de confirmation pour un atelier de gestion de trésorerie à l’accueil.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier de gestion de trésorerie.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de gestion de trésorerie."],"correct":"B","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier de gestion de trésorerie à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de gestion de trésorerie, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de gestion de trésorerie, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.85,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance prévue pour un atelier de gestion de trésorerie commence une heure plus tard.","La séance de un atelier de gestion de trésorerie commence une heure plus tôt que prévu.","La séance de un atelier de gestion de trésorerie est reportée au lendemain à la même heure.","La séance de un atelier de gestion de trésorerie change de salle mais garde le même horaire."],"correct":"A","explanation":"Le document permet de retenir « La séance prévue pour un atelier de gestion de trésorerie commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de gestion de trésorerie. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de gestion de trésorerie. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.332,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Reporter un atelier de gestion de trésorerie jusqu’à ce que le matériel soit disponible.","Garder un atelier de gestion de trésorerie mais renoncer à fournir la démonstration prévue.","Maintenir un atelier de gestion de trésorerie avec une démonstration réalisée sans le matériel.","Conserver un atelier de gestion de trésorerie et envoyer ensuite la démonstration manquante."],"correct":"D","explanation":"Le document permet de retenir « Conserver un atelier de gestion de trésorerie et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de gestion de trésorerie n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de gestion de trésorerie n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":31.024,"slotSeconds":48},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans la chambre de commerce d'Amiens, l’initiative est désormais réservée aux habitués.","Dans la chambre de commerce d'Amiens, la mesure a été suspendue faute de participants.","La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans la chambre de commerce d'Amiens, les difficultés ont été réglées avant le lancement."],"correct":"C","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la chambre de commerce d'Amiens : un accompagnement gratuit à la transition numérique. Le dispositif vise à répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges. Plusieurs représentants soulignent toutefois que les délais de livraison sont parfois difficiles à anticiper. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la chambre de commerce d'Amiens : un accompagnement gratuit à la transition numérique. Le dispositif vise à répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges. Plusieurs représentants soulignent toutefois que les délais de livraison sont parfois difficiles à anticiper. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":31.84,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Avancer les horaires de le mentorat des commerces indépendants en supprimant le relais du soir.","Réorganiser les permanences afin de maintenir un accueil pour le mentorat des commerces indépendants toute la journée.","Réserver les permanences de le mentorat des commerces indépendants aux inscriptions du matin.","Répartir les permanences de le mentorat des commerces indépendants entre deux lieux différents."],"correct":"B","explanation":"Le document permet de retenir « Réorganiser les permanences afin de maintenir un accueil pour le mentorat des commerces indépendants toute la journée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le mentorat des commerces indépendants.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le mentorat des commerces indépendants."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":24.9,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui rencontrent des obstacles dans la chambre de commerce d'Amiens.","Les personnes qui fréquentent régulièrement les ateliers de la chambre de commerce d'Amiens.","Les employés chargés d’accueillir et d’orienter les visiteurs de la chambre de commerce d'Amiens.","Les visiteurs ayant déjà terminé leurs démarches dans la chambre de commerce d'Amiens."],"correct":"A","explanation":"Le document permet de retenir « Les personnes qui rencontrent des obstacles dans la chambre de commerce d'Amiens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la chambre de commerce d'Amiens. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les petites entreprises manquent de marge pour absorber les hausses de charges. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la chambre de commerce d'Amiens. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les petites entreprises manquent de marge pour absorber les hausses de charges. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":29.902,"slotSeconds":46},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle demande un autre horaire pour une rencontre des petits entrepreneurs afin d’accompagner un proche.","Elle ne peut se rendre à une rencontre des petits entrepreneurs à cause d’un retard de transport.","Elle souhaite déplacer une rencontre des petits entrepreneurs à cause d’un changement de salle.","Elle travaille encore vendredi à seize heures, au moment d’une rencontre des petits entrepreneurs."],"correct":"D","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une rencontre des petits entrepreneurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une rencontre des petits entrepreneurs. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une rencontre des petits entrepreneurs. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.693,"slotSeconds":47},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Réduire le groupe de une rencontre des petits entrepreneurs pour utiliser moins de matériel.","Adapter le nombre de places de une rencontre des petits entrepreneurs à la taille de la salle.","Le petit groupe permet d’échanger davantage pendant une rencontre des petits entrepreneurs.","Répartir les participants de une rencontre des petits entrepreneurs selon leur expérience."],"correct":"C","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant une rencontre des petits entrepreneurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une rencontre des petits entrepreneurs, des visites en petits groupes seront proposées dans la chambre de commerce d'Amiens. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une rencontre des petits entrepreneurs, des visites en petits groupes seront proposées dans la chambre de commerce d'Amiens. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.758,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle veut savoir comment les horaires des séances seront communiqués.","La visiteuse souhaite des précisions sur la prévisibilité des coûts et l'accès au financement.","Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet."],"correct":"B","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la prévisibilité des coûts et l'accès au financement ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la prévisibilité des coûts et l'accès au financement. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la prévisibilité des coûts et l'accès au financement. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.542,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Répartir les bénévoles selon les horaires prévus pour une rencontre des petits entrepreneurs.","Définir les activités prioritaires selon le public attendu pour une rencontre des petits entrepreneurs.","Adapter les tâches des bénévoles aux compétences requises pour une rencontre des petits entrepreneurs.","Prévoir le matériel nécessaire selon les inscriptions à une rencontre des petits entrepreneurs."],"correct":"A","explanation":"Le document permet de retenir « Répartir les bénévoles selon les horaires prévus pour une rencontre des petits entrepreneurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la chambre de commerce d'Amiens, pour préparer une rencontre des petits entrepreneurs, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la chambre de commerce d'Amiens, pour préparer une rencontre des petits entrepreneurs, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.417,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les connaissances pratiques acquises au cours de un atelier de gestion de trésorerie.","Les nouveaux contacts professionnels pris pendant un atelier de gestion de trésorerie.","La meilleure organisation des activités obtenue grâce à un atelier de gestion de trésorerie.","Les relations de confiance créées autour d’un atelier de gestion de trésorerie."],"correct":"D","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de gestion de trésorerie ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de gestion de trésorerie. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les petites entreprises manquent de marge pour absorber les hausses de charges. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de gestion de trésorerie. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les petites entreprises manquent de marge pour absorber les hausses de charges. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":44.672,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Consulter les habitants sur des achats mutualisés et des conseils adaptés à chaque activité sans mener d’essai concret.","Expérimenter des achats mutualisés et des conseils adaptés à chaque activité mais ne publier aucun retour des participants.","Expérimenter des achats mutualisés et des conseils adaptés à chaque activité, recueillir les avis et publier un bilan.","Mettre en place des achats mutualisés et des conseils adaptés à chaque activité partout avant de mesurer les résultats."],"correct":"C","explanation":"Le document permet de retenir « Expérimenter des achats mutualisés et des conseils adaptés à chaque activité, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Économie et entreprises ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des achats mutualisés et des conseils adaptés à chaque activité.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les petites entreprises manquent de marge pour absorber les hausses de charges.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Économie et entreprises »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des achats mutualisés et des conseils adaptés à chaque activité."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les petites entreprises manquent de marge pour absorber les hausses de charges."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":55.03,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le mentorat des commerces indépendants s’appuie principalement sur les réponses des agents.","L’étude sur le mentorat des commerces indépendants n’a presque pas touché ceux qui ont abandonné.","L’étude de le mentorat des commerces indépendants donne peu de place aux nouveaux inscrits.","L’étude de le mentorat des commerces indépendants comprend surtout des personnes en attente."],"correct":"B","explanation":"Le document permet de retenir « L’étude sur le mentorat des commerces indépendants n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le mentorat des commerces indépendants. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les petites entreprises manquent de marge pour absorber les hausses de charges. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le mentorat des commerces indépendants. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les petites entreprises manquent de marge pour absorber les hausses de charges. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.354,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quel équilibre les responsables cherchent-ils à établir ?","options":["Mutualiser les achats tout en préservant une activité financièrement viable.","Fixer les mêmes budgets pour toutes les structures, quels que soient leurs besoins.","Remplacer les conseils individualisés par des règles d’achat identiques.","Dépendre principalement des subventions pour financer chaque commande."],"correct":"A","explanation":"Le reportage articule achats mutualisés, conseils adaptés et financement durable, avec des coûts et délais encore incertains. Les autres réponses imposent une uniformité ou une dépendance financière contraire aux objectifs exprimés.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la chambre de commerce d'Amiens, une initiative propose des achats mutualisés et des conseils adaptés à chaque activité. Les responsables espèrent ainsi répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges.\nNous soutenons l’objectif général, mais il faut prendre en compte la prévisibilité des coûts et l'accès au financement. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils veulent diversifier les revenus afin de réduire leur dépendance aux subventions. Pourtant, les délais de livraison sont parfois difficiles à anticiper. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuel équilibre les responsables cherchent-ils à établir ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la chambre de commerce d'Amiens, une initiative propose des achats mutualisés et des conseils adaptés à chaque activité. Les responsables espèrent ainsi répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la prévisibilité des coûts et l'accès au financement. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils veulent diversifier les revenus afin de réduire leur dépendance aux subventions. Pourtant, les délais de livraison sont parfois difficiles à anticiper. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quel équilibre les responsables cherchent-ils à établir ?"}],"slotSeconds":72,"audio":"q-25.mp3","audioSeconds":53.736},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les résultats de un accompagnement gratuit à la transition numérique concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre un accompagnement gratuit à la transition numérique dès la fin des premiers essais.","Le projet de un accompagnement gratuit à la transition numérique est annoncé mais n’a pas encore été lancé.","Les premiers effets d’un accompagnement gratuit à la transition numérique doivent être vérifiés dans la durée."],"correct":"D","explanation":"Le document permet de retenir « Les premiers effets d’un accompagnement gratuit à la transition numérique doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé un accompagnement gratuit à la transition numérique. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les délais de livraison sont parfois difficiles à anticiper. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la viabilité des entreprises au-delà de leur première année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé un accompagnement gratuit à la transition numérique. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les délais de livraison sont parfois difficiles à anticiper. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la viabilité des entreprises au-delà de leur première année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.594,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Réserver les créneaux matinaux de le mentorat des commerces indépendants aux seuls abonnés.","Ouvrir le mentorat des commerces indépendants plus tôt en supprimant les créneaux tardifs.","Adapter les horaires du mentorat des commerces indépendants sans pénaliser les usagers du soir.","Conserver les horaires de le mentorat des commerces indépendants malgré les demandes du matin."],"correct":"C","explanation":"Le document permet de retenir « Adapter les horaires du mentorat des commerces indépendants sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le mentorat des commerces indépendants ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le mentorat des commerces indépendants ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.073,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Préparer le budget de un espace de vente collectif avant de calculer son entretien.","Les équipements d’un espace de vente collectif ont été choisis avant la consultation des futurs usagers.","Adapter les équipements de un espace de vente collectif après consultation des équipes.","Tester un espace de vente collectif sur un seul site avant de l’ouvrir à tous."],"correct":"B","explanation":"Le document permet de retenir « Les équipements d’un espace de vente collectif ont été choisis avant la consultation des futurs usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un espace de vente collectif a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la prévisibilité des coûts et l'accès au financement est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un espace de vente collectif a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la prévisibilité des coûts et l'accès au financement est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":50.359,"slotSeconds":68},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut mesurer la viabilité des entreprises au-delà de leur première année ; l’autre demande des récits.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de la viabilité des entreprises au-delà de leur première année ; l’autre mesure la fréquentation."],"correct":"A","explanation":"Le document permet de retenir « L’un veut mesurer la viabilité des entreprises au-delà de leur première année ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Économie et entreprises ».\nSans chiffres comparables, impossible de dire si un accompagnement gratuit à la transition numérique apporte un bénéfice mesurable. Nous devons étudier la viabilité des entreprises au-delà de leur première année.\nLes chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les petites entreprises manquent de marge pour absorber les hausses de charges.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Économie et entreprises »."},{"voice":"male","text":"Sans chiffres comparables, impossible de dire si un accompagnement gratuit à la transition numérique apporte un bénéfice mesurable. Nous devons étudier la viabilité des entreprises au-delà de leur première année."},{"voice":"female","text":"Les chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les petites entreprises manquent de marge pour absorber les hausses de charges."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":47.552,"slotSeconds":65},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Moderniser les salles de un atelier de gestion de trésorerie en effaçant les anciennes traces.","Rénover le lieu de un atelier de gestion de trésorerie sans changer l’usage actuel des espaces.","Conserver le bâtiment de un atelier de gestion de trésorerie uniquement pour ses activités passées.","Préserver l’histoire du lieu d’un atelier de gestion de trésorerie tout en y proposant de nouveaux usages."],"correct":"D","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de gestion de trésorerie tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de gestion de trésorerie, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de gestion de trésorerie, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.636,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Comparer les progrès enregistrés lors des deux premières semaines.","Mesurer l’évolution d’un projet uniquement pendant son lancement.","Distinguer une amélioration immédiate d’un changement durable.","Suivre seulement les personnes arrivées au cours du premier mois."],"correct":"C","explanation":"Le document permet de retenir « Distinguer une amélioration immédiate d’un changement durable ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la viabilité des entreprises au-delà de leur première année. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les petites entreprises manquent de marge pour absorber les hausses de charges. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la viabilité des entreprises au-delà de leur première année. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les petites entreprises manquent de marge pour absorber les hausses de charges. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":53.876,"slotSeconds":71},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le mentorat des commerces indépendants, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le mentorat des commerces indépendants, présenter les hypothèses et les incertitudes des prévisions.","Pour le mentorat des commerces indépendants, publier un chiffre précis sans détailler ses limites.","Pour le mentorat des commerces indépendants, annoncer une moyenne sans préciser les hypothèses retenues."],"correct":"B","explanation":"Le document permet de retenir « Pour le mentorat des commerces indépendants, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le mentorat des commerces indépendants, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le mentorat des commerces indépendants, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.321,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites ne démontre pas un bénéfice durable du projet.","La hausse des visites à la chambre de commerce d'Amiens vient surtout des horaires étendus.","La fréquentation de la chambre de commerce d'Amiens varie trop selon les saisons.","Les chiffres de la chambre de commerce d'Amiens ne tiennent pas compte du prix des activités."],"correct":"A","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la chambre de commerce d'Amiens, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un accompagnement gratuit à la transition numérique. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la viabilité des entreprises au-delà de leur première année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la chambre de commerce d'Amiens, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un accompagnement gratuit à la transition numérique. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la viabilité des entreprises au-delà de leur première année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.199,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester le mentorat des commerces indépendants uniquement par les usagers réguliers.","Maintenir une aide humaine à le mentorat des commerces indépendants pendant le seul lancement.","Évaluer le mentorat des commerces indépendants auprès de tous puis supprimer l’accueil individuel.","Faire tester le mentorat des commerces indépendants par divers publics, avec une aide humaine conservée."],"correct":"D","explanation":"Le document permet de retenir « Faire tester le mentorat des commerces indépendants par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la chambre de commerce d'Amiens.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la prévisibilité des coûts et l'accès au financement.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la chambre de commerce d'Amiens."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la prévisibilité des coûts et l'accès au financement."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":54.113,"slotSeconds":72},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les usages quotidiens du matériel de la pépinière d'entreprises peuvent changer ses effets.","Les conditions de terrain de la pépinière d'entreprises influencent les résultats observés.","Les résultats techniques de la pépinière d'entreprises suffiraient même si les usages réels diffèrent.","La performance du dispositif de la pépinière d'entreprises exige un entretien régulier."],"correct":"C","explanation":"Le document permet de retenir « Les résultats techniques de la pépinière d'entreprises suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la pépinière d'entreprises affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la pépinière d'entreprises affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.382,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Évaluer le lien créé à un atelier de gestion de trésorerie uniquement par le nombre de présences.","Le volontariat et les échanges réciproques pendant un atelier de gestion de trésorerie renforcent les liens.","Assurer une présence régulière aux séances de un atelier de gestion de trésorerie sans échanger.","Répartir les rôles de un atelier de gestion de trésorerie entre des participants désignés à l’avance."],"correct":"B","explanation":"Le document permet de retenir « Le volontariat et les échanges réciproques pendant un atelier de gestion de trésorerie renforcent les liens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de gestion de trésorerie réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la prévisibilité des coûts et l'accès au financement. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de gestion de trésorerie réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la prévisibilité des coûts et l'accès au financement. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":53.517,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits concernant le mentorat des commerces indépendants aux faits vérifiables.","Conserver les récits de le mentorat des commerces indépendants qui concordent avec la majorité.","Classer les témoignages de le mentorat des commerces indépendants selon l’ancienneté de leurs auteurs.","Comparer les récits de le mentorat des commerces indépendants sans consulter les archives disponibles."],"correct":"A","explanation":"Le document permet de retenir « Comparer les récits concernant le mentorat des commerces indépendants aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le mentorat des commerces indépendants, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le mentorat des commerces indépendants, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.703,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La fréquentation de un accompagnement gratuit à la transition numérique ralentit la promotion du dispositif.","La croissance de un accompagnement gratuit à la transition numérique augmente le budget sans effet sur les usagers.","Le succès de un accompagnement gratuit à la transition numérique réduit les demandes des services voisins.","Le succès d’un accompagnement gratuit à la transition numérique peut créer des difficultés aux usagers."],"correct":"D","explanation":"Le document permet de retenir « Le succès d’un accompagnement gratuit à la transition numérique peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Économie et entreprises ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accompagnement gratuit à la transition numérique peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les petites entreprises manquent de marge pour absorber les hausses de charges. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la prévisibilité des coûts et l'accès au financement. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Économie et entreprises ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accompagnement gratuit à la transition numérique peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les petites entreprises manquent de marge pour absorber les hausses de charges. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la prévisibilité des coûts et l'accès au financement. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":64.255,"slotSeconds":82},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Étendre le service en privilégiant seulement les premiers résultats de la viabilité des entreprises au-delà de leur première année.","Suivre la viabilité des entreprises au-delà de leur première année en comptant sur les bénévoles actuels.","Assurer des moyens durables et suivre la viabilité des entreprises au-delà de leur première année sur la durée.","Obtenir des moyens durables mais ne plus mesurer la viabilité des entreprises au-delà de leur première année."],"correct":"C","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre la viabilité des entreprises au-delà de leur première année sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le mentorat des commerces indépendants, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les délais de livraison sont parfois difficiles à anticiper. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la viabilité des entreprises au-delà de leur première année. L’idée n’est pas d’abandonner l’ambition de départ : diversifier les revenus et éviter la dépendance aux subventions. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le mentorat des commerces indépendants, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les délais de livraison sont parfois difficiles à anticiper. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la viabilité des entreprises au-delà de leur première année. L’idée n’est pas d’abandonner l’ambition de départ : diversifier les revenus et éviter la dépendance aux subventions. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.798,"slotSeconds":81}]},{"id":"tcf-listening-18","version":"tcf-listening-2026-11-test18-v2","title":"TCF Listening · Test 18","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La scène représente une personne assise, occupée à consulter une photographie ancienne.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle répare le moteur d'une voiture. B. Elle consulte une photographie ancienne à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle répare le moteur d'une voiture. B. Elle consulte une photographie ancienne à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.943,"slotSeconds":32},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Un homme présente une affiche liée à histoire et patrimoine.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il présente une affiche sur histoire et patrimoine à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il présente une affiche sur histoire et patrimoine à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.56,"slotSeconds":32},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Deux interlocuteurs préparent une semaine du patrimoine autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une semaine du patrimoine autour d'une table.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une semaine du patrimoine autour d'une table."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.186,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'illustration montre une personne portant un sac devant les archives municipales de Caen.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant les archives municipales de Caen. D. Une femme nage dans une piscine.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant les archives municipales de Caen. D. Une femme nage dans une piscine."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.779,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de recherche généalogique ?\nA. La météo annonce de la pluie. B. Dans la salle du premier étage, juste après l'accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de recherche généalogique ?"},{"voice":"female","text":"A. La météo annonce de la pluie. B. Dans la salle du premier étage, juste après l'accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir."}],"audio":"q-05.mp3","audioSeconds":19.679,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter une photographie ancienne pour participer à une semaine du patrimoine ?\nA. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter une photographie ancienne pour participer à une semaine du patrimoine ?"},{"voice":"female","text":"A. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie."}],"audio":"q-06.mp3","audioSeconds":20.184,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de recherche généalogique ?\nA. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de recherche généalogique ?"},{"voice":"female","text":"A. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée."}],"audio":"q-07.mp3","audioSeconds":17.705,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une semaine du patrimoine. Est-ce possible ?\nA. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une semaine du patrimoine. Est-ce possible ?"},{"voice":"female","text":"A. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver."}],"audio":"q-08.mp3","audioSeconds":21.217,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Une adaptation des tarifs des activités déjà annoncées.","Une consultation libre des registres le samedi.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles."],"correct":"B","explanation":"Le document permet de retenir « Une consultation libre des registres le samedi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans les archives municipales de Caen, à compter de lundi prochain, nous mettons en place une consultation libre des registres le samedi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans les archives municipales de Caen, à compter de lundi prochain, nous mettons en place une consultation libre des registres le samedi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.937,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous d’un atelier de recherche généalogique est repoussé à cause d’une réunion prolongée.","Le rendez-vous pour un atelier de recherche généalogique est reporté au lendemain.","Un autre créneau est proposé pour un atelier de recherche généalogique en raison des transports.","Le rendez-vous pour un atelier de recherche généalogique est avancé d’une demi-heure."],"correct":"A","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de recherche généalogique est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de recherche généalogique ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de recherche généalogique ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.332,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Déposer sa demande pour une semaine du patrimoine à l’accueil le jour même.","Réserver sa place pour une semaine du patrimoine par téléphone avant jeudi.","Envoyer le formulaire de une semaine du patrimoine par courriel avant vendredi.","Pour une semaine du patrimoine, le formulaire doit être rempli en ligne avant jeudi."],"correct":"D","explanation":"Le document permet de retenir « Pour une semaine du patrimoine, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Histoire et patrimoine » aura lieu dans les archives municipales de Caen. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Histoire et patrimoine » aura lieu dans les archives municipales de Caen. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.886,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Présenter une pièce d’identité à l’accueil pour accéder à un atelier de recherche généalogique.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de recherche généalogique.","Présenter le message de confirmation pour un atelier de recherche généalogique à l’accueil.","Demander une confirmation écrite après la fin de un atelier de recherche généalogique."],"correct":"C","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier de recherche généalogique à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de recherche généalogique, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de recherche généalogique, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.35,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de recherche généalogique est reportée au lendemain à la même heure.","La séance d’un atelier de recherche généalogique est décalée à quinze heures, au même endroit.","La séance de un atelier de recherche généalogique change de salle mais garde le même horaire.","La séance de un atelier de recherche généalogique commence une heure plus tôt que prévu."],"correct":"B","explanation":"Le document permet de retenir « La séance d’un atelier de recherche généalogique est décalée à quinze heures, au même endroit ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de recherche généalogique. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de recherche généalogique. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.33,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Conserver un atelier de recherche généalogique et envoyer la démonstration plus tard.","Garder un atelier de recherche généalogique mais renoncer à fournir la démonstration prévue.","Maintenir un atelier de recherche généalogique avec une démonstration réalisée sans le matériel.","Reporter un atelier de recherche généalogique jusqu’à ce que le matériel soit disponible."],"correct":"A","explanation":"Le document permet de retenir « Conserver un atelier de recherche généalogique et envoyer la démonstration plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de recherche généalogique n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de recherche généalogique n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.293,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans les archives municipales de Caen, la mesure a été suspendue faute de participants.","Dans les archives municipales de Caen, les difficultés ont été réglées avant le lancement.","Dans les archives municipales de Caen, l’initiative est désormais réservée aux habitués.","La mesure répond à un besoin local, mais certaines difficultés persistent."],"correct":"D","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans les archives municipales de Caen : une consultation libre des registres le samedi. Le dispositif vise à répondre à une difficulté bien connue : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Plusieurs représentants soulignent toutefois que certains documents fragiles ne peuvent plus être manipulés directement. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans les archives municipales de Caen : une consultation libre des registres le samedi. Le dispositif vise à répondre à une difficulté bien connue : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Plusieurs représentants soulignent toutefois que certains documents fragiles ne peuvent plus être manipulés directement. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.316,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Réserver les permanences de la numérisation des archives familiales aux inscriptions du matin.","Répartir les permanences de la numérisation des archives familiales entre deux lieux différents.","Répartir les permanences de la numérisation des archives familiales pour maintenir l’accueil continu.","Avancer les horaires de la numérisation des archives familiales en supprimant le relais du soir."],"correct":"C","explanation":"Le document permet de retenir « Répartir les permanences de la numérisation des archives familiales pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la numérisation des archives familiales.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la numérisation des archives familiales."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.875,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les employés chargés d’accueillir et d’orienter les visiteurs de les archives municipales de Caen.","Les visiteurs de les archives municipales de Caen qui peinent à accéder au service ordinaire.","Les visiteurs ayant déjà terminé leurs démarches dans les archives municipales de Caen.","Les personnes qui fréquentent régulièrement les ateliers de les archives municipales de Caen."],"correct":"B","explanation":"Le document permet de retenir « Les visiteurs de les archives municipales de Caen qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans les archives municipales de Caen. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans les archives municipales de Caen. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":29.948,"slotSeconds":45},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["La personne travaille à l’heure prévue pour une semaine du patrimoine.","Elle ne peut se rendre à une semaine du patrimoine à cause d’un retard de transport.","Elle souhaite déplacer une semaine du patrimoine à cause d’un changement de salle.","Elle demande un autre horaire pour une semaine du patrimoine afin d’accompagner un proche."],"correct":"A","explanation":"Le document permet de retenir « La personne travaille à l’heure prévue pour une semaine du patrimoine ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une semaine du patrimoine. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une semaine du patrimoine. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.886,"slotSeconds":45},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Adapter le nombre de places de une semaine du patrimoine à la taille de la salle.","Répartir les participants de une semaine du patrimoine selon leur expérience.","Réduire le groupe de une semaine du patrimoine pour utiliser moins de matériel.","Le petit groupe permet d’échanger davantage pendant une semaine du patrimoine."],"correct":"D","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant une semaine du patrimoine ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une semaine du patrimoine, des visites en petits groupes seront proposées dans les archives municipales de Caen. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une semaine du patrimoine, des visites en petits groupes seront proposées dans les archives municipales de Caen. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.549,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet.","La visiteuse souhaite des précisions sur la distinction entre mémoire personnelle et preuve historique.","Elle veut savoir comment les horaires des séances seront communiqués."],"correct":"C","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la distinction entre mémoire personnelle et preuve historique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la distinction entre mémoire personnelle et preuve historique. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la distinction entre mémoire personnelle et preuve historique. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.775,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Adapter les tâches des bénévoles aux compétences requises pour une semaine du patrimoine.","Répartir les bénévoles d’une semaine du patrimoine selon les créneaux où ils sont libres.","Prévoir le matériel nécessaire selon les inscriptions à une semaine du patrimoine.","Définir les activités prioritaires selon le public attendu pour une semaine du patrimoine."],"correct":"B","explanation":"Le document permet de retenir « Répartir les bénévoles d’une semaine du patrimoine selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans les archives municipales de Caen, pour préparer une semaine du patrimoine, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans les archives municipales de Caen, pour préparer une semaine du patrimoine, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.705,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les relations de confiance créées autour d’un atelier de recherche généalogique.","Les nouveaux contacts professionnels pris pendant un atelier de recherche généalogique.","La meilleure organisation des activités obtenue grâce à un atelier de recherche généalogique.","Les connaissances pratiques acquises au cours de un atelier de recherche généalogique."],"correct":"A","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de recherche généalogique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de recherche généalogique. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de recherche généalogique. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.593,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Expérimenter des restaurations documentées et des usages compatibles avec la conservation mais ne publier aucun retour des participants.","Mettre en place des restaurations documentées et des usages compatibles avec la conservation partout avant de mesurer les résultats.","Consulter les habitants sur des restaurations documentées et des usages compatibles avec la conservation sans mener d’essai concret.","Expérimenter des restaurations documentées et des usages compatibles avec la conservation, recueillir les avis et publier un bilan."],"correct":"D","explanation":"Le document permet de retenir « Expérimenter des restaurations documentées et des usages compatibles avec la conservation, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Histoire et patrimoine ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des restaurations documentées et des usages compatibles avec la conservation.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Histoire et patrimoine »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des restaurations documentées et des usages compatibles avec la conservation."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":55.344,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de la numérisation des archives familiales donne peu de place aux nouveaux inscrits.","L’étude de la numérisation des archives familiales comprend surtout des personnes en attente.","L’étude sur la numérisation des archives familiales n’a presque pas touché ceux qui ont abandonné.","L’étude de la numérisation des archives familiales s’appuie principalement sur les réponses des agents."],"correct":"C","explanation":"Le document permet de retenir « L’étude sur la numérisation des archives familiales n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant la numérisation des archives familiales. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant la numérisation des archives familiales. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":51.967,"slotSeconds":68},{"number":25,"kind":"television-report","question":"Quelle contrainte complique la préservation évoquée dans le reportage ?","options":["Les équipes souhaitent remplacer les archives par des souvenirs non vérifiés.","Conserver les documents tout en limitant la manipulation des pièces fragiles.","Les responsables refusent de former de nouveaux spécialistes des archives.","Les visiteurs demandent tous un accès immédiat aux documents originaux."],"correct":"B","explanation":"Le reportage prévoit des restaurations documentées et rappelle que certains documents sont trop fragiles pour être manipulés directement. Il ne préconise ni l’abandon des sources ni l’arrêt de la formation.","transcript":"Question 25.\nVous regardez un reportage régional. Dans les archives municipales de Caen, une initiative propose des restaurations documentées et des usages compatibles avec la conservation. Les responsables espèrent ainsi répondre à une difficulté bien connue : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent.\nNous soutenons l’objectif général, mais il faut prendre en compte la distinction entre mémoire personnelle et preuve historique. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils veulent préserver les sources et former une nouvelle génération de professionnels de la conservation. Pourtant, certains documents fragiles ne peuvent plus être manipulés directement. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle contrainte complique la préservation évoquée dans le reportage ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans les archives municipales de Caen, une initiative propose des restaurations documentées et des usages compatibles avec la conservation. Les responsables espèrent ainsi répondre à une difficulté bien connue : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la distinction entre mémoire personnelle et preuve historique. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils veulent préserver les sources et former une nouvelle génération de professionnels de la conservation. Pourtant, certains documents fragiles ne peuvent plus être manipulés directement. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle contrainte complique la préservation évoquée dans le reportage ?"}],"slotSeconds":75,"audio":"q-25.mp3","audioSeconds":56.991},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les premiers effets d’une consultation libre des registres le samedi doivent être vérifiés dans la durée.","L’équipe souhaite interrompre une consultation libre des registres le samedi dès la fin des premiers essais.","Le projet de une consultation libre des registres le samedi est annoncé mais n’a pas encore été lancé.","Les résultats de une consultation libre des registres le samedi concernent uniquement les coûts de gestion."],"correct":"A","explanation":"Le document permet de retenir « Les premiers effets d’une consultation libre des registres le samedi doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une consultation libre des registres le samedi. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certains documents fragiles ne peuvent plus être manipulés directement. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une consultation libre des registres le samedi. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certains documents fragiles ne peuvent plus être manipulés directement. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":49.883,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Ouvrir la numérisation des archives familiales plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de la numérisation des archives familiales malgré les demandes du matin.","Réserver les créneaux matinaux de la numérisation des archives familiales aux seuls abonnés.","Adapter les horaires de la numérisation des archives familiales sans pénaliser les usagers du soir."],"correct":"D","explanation":"Le document permet de retenir « Adapter les horaires de la numérisation des archives familiales sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que la numérisation des archives familiales ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que la numérisation des archives familiales ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":42.281,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Adapter les équipements de une salle de consultation des manuscrits après consultation des équipes.","Tester une salle de consultation des manuscrits sur un seul site avant de l’ouvrir à tous.","Concevoir une salle de consultation des manuscrits avant de comprendre les besoins réels des utilisateurs.","Préparer le budget de une salle de consultation des manuscrits avant de calculer son entretien."],"correct":"C","explanation":"Le document permet de retenir « Concevoir une salle de consultation des manuscrits avant de comprendre les besoins réels des utilisateurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de une salle de consultation des manuscrits a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la distinction entre mémoire personnelle et preuve historique est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une salle de consultation des manuscrits a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la distinction entre mémoire personnelle et preuve historique est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":50.411,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent; l’autre demande aussi des témoignages.","L’un veut comparer les coûts de l'état des collections et la diversité des publics qui y accèdent ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières."],"correct":"B","explanation":"Le document permet de retenir « L’un veut suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent; l’autre demande aussi des témoignages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Histoire et patrimoine ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Histoire et patrimoine »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : l'état des collections et la diversité des publics qui y accèdent et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":52.405,"slotSeconds":69},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Préserver l’histoire du lieu d’un atelier de recherche généalogique tout en y proposant de nouveaux usages.","Rénover le lieu de un atelier de recherche généalogique sans changer l’usage actuel des espaces.","Conserver le bâtiment de un atelier de recherche généalogique uniquement pour ses activités passées.","Moderniser les salles de un atelier de recherche généalogique en effaçant les anciennes traces."],"correct":"A","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de recherche généalogique tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de recherche généalogique, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de recherche généalogique, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.323,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Comparer la moyenne d’un groupe à la moyenne de l’ensemble.","Privilégier les chiffres globaux plutôt que les résultats détaillés.","Calculer une nouvelle moyenne globale avec davantage de données.","Examiner les différences entre groupes, cachées par une moyenne."],"correct":"D","explanation":"Le document permet de retenir « Examiner les différences entre groupes, cachées par une moyenne ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, l'état des collections et la diversité des publics qui y accèdent. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, l'état des collections et la diversité des publics qui y accèdent. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":55.931,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour la numérisation des archives familiales, publier un chiffre précis sans détailler ses limites.","Pour la numérisation des archives familiales, annoncer une moyenne sans préciser les hypothèses retenues.","Pour la numérisation des archives familiales, présenter les hypothèses et les incertitudes des prévisions.","Pour la numérisation des archives familiales, accorder la même fiabilité à toutes les prévisions disponibles."],"correct":"C","explanation":"Le document permet de retenir « Pour la numérisation des archives familiales, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant la numérisation des archives familiales, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant la numérisation des archives familiales, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.199,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La fréquentation de les archives municipales de Caen varie trop selon les saisons.","La hausse de fréquentation dans les archives municipales de Caen ne suffit pas à mesurer les résultats durables.","Les chiffres de les archives municipales de Caen ne tiennent pas compte du prix des activités.","La hausse des visites à les archives municipales de Caen vient surtout des horaires étendus."],"correct":"B","explanation":"Le document permet de retenir « La hausse de fréquentation dans les archives municipales de Caen ne suffit pas à mesurer les résultats durables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans les archives municipales de Caen, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une consultation libre des registres le samedi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer l'état des collections et la diversité des publics qui y accèdent ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans les archives municipales de Caen, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une consultation libre des registres le samedi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer l'état des collections et la diversité des publics qui y accèdent ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":49.511,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester la numérisation des archives familiales par divers publics, avec une aide humaine conservée.","Maintenir une aide humaine à la numérisation des archives familiales pendant le seul lancement.","Évaluer la numérisation des archives familiales auprès de tous puis supprimer l’accueil individuel.","Faire tester la numérisation des archives familiales uniquement par les usagers réguliers."],"correct":"A","explanation":"Le document permet de retenir « Faire tester la numérisation des archives familiales par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans les archives municipales de Caen.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la distinction entre mémoire personnelle et preuve historique.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans les archives municipales de Caen."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la distinction entre mémoire personnelle et preuve historique."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":54.659,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les conditions de terrain de l'ancienne halle industrielle influencent les résultats observés.","La performance du dispositif de l'ancienne halle industrielle exige un entretien régulier.","Les usages quotidiens du matériel de l'ancienne halle industrielle peuvent changer ses effets.","Les résultats techniques de l'ancienne halle industrielle suffiraient même si les usages réels diffèrent."],"correct":"D","explanation":"Le document permet de retenir « Les résultats techniques de l'ancienne halle industrielle suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans l'ancienne halle industrielle affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans l'ancienne halle industrielle affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.127,"slotSeconds":67},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Assurer une présence régulière aux séances de un atelier de recherche généalogique sans échanger.","Répartir les rôles de un atelier de recherche généalogique entre des participants désignés à l’avance.","Permettre une participation volontaire et réciproque à un atelier de recherche généalogique.","Évaluer le lien créé à un atelier de recherche généalogique uniquement par le nombre de présences."],"correct":"C","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de recherche généalogique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de recherche généalogique réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la distinction entre mémoire personnelle et preuve historique. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de recherche généalogique réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la distinction entre mémoire personnelle et preuve historique. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.156,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Classer les témoignages de la numérisation des archives familiales selon l’ancienneté de leurs auteurs.","La chercheuse confronte les témoignages sur la numérisation des archives familiales aux dates et décisions vérifiables.","Comparer les récits de la numérisation des archives familiales sans consulter les archives disponibles.","Conserver les récits de la numérisation des archives familiales qui concordent avec la majorité."],"correct":"B","explanation":"Le document permet de retenir « La chercheuse confronte les témoignages sur la numérisation des archives familiales aux dates et décisions vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant la numérisation des archives familiales, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant la numérisation des archives familiales, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.633,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès d’une consultation libre des registres le samedi peut créer des difficultés aux usagers.","La croissance de une consultation libre des registres le samedi augmente le budget sans effet sur les usagers.","Le succès de une consultation libre des registres le samedi réduit les demandes des services voisins.","La fréquentation de une consultation libre des registres le samedi ralentit la promotion du dispositif."],"correct":"A","explanation":"Le document permet de retenir « Le succès d’une consultation libre des registres le samedi peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Histoire et patrimoine ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une consultation libre des registres le samedi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la distinction entre mémoire personnelle et preuve historique. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Histoire et patrimoine ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une consultation libre des registres le samedi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les bâtiments anciens se dégradent quand les budgets d'entretien diminuent. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la distinction entre mémoire personnelle et preuve historique. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":65.068,"slotSeconds":83},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Suivre l'état des collections et la diversité des publics qui y accèdent en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer l'état des collections et la diversité des publics qui y accèdent.","Étendre le service en privilégiant seulement les premiers résultats de l'état des collections et la diversité des publics qui y accèdent.","Assurer des moyens durables et suivre l'état des collections et la diversité des publics qui y accèdent sur la durée."],"correct":"D","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre l'état des collections et la diversité des publics qui y accèdent sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à la numérisation des archives familiales, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certains documents fragiles ne peuvent plus être manipulés directement. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre l'état des collections et la diversité des publics qui y accèdent. L’idée n’est pas d’abandonner l’ambition de départ : préserver les sources et former de nouveaux professionnels de la conservation. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à la numérisation des archives familiales, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certains documents fragiles ne peuvent plus être manipulés directement. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre l'état des collections et la diversité des publics qui y accèdent. L’idée n’est pas d’abandonner l’ambition de départ : préserver les sources et former de nouveaux professionnels de la conservation. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":65.667,"slotSeconds":83}]},{"id":"tcf-listening-19","version":"tcf-listening-2026-11-test19-v2","title":"TCF Listening · Test 19","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La scène représente une personne assise, occupée à consulter un bulletin de participation.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un bulletin de participation à une table. D. Elle court sur un terrain de sport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un bulletin de participation à une table. D. Elle court sur un terrain de sport."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.268,"slotSeconds":33},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Un homme présente une affiche liée à citoyenneté et politiques publiques.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il peint une façade extérieure. B. Il présente une affiche sur citoyenneté et politiques publiques à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il peint une façade extérieure. B. Il présente une affiche sur citoyenneté et politiques publiques à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":18.245,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Deux interlocuteurs préparent une assemblée citoyenne autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes préparent une assemblée citoyenne autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes préparent une assemblée citoyenne autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.826,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'illustration montre une personne portant un sac devant la mairie de Strasbourg.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant la mairie de Strasbourg.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant la mairie de Strasbourg."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":17.978,"slotSeconds":33},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de budget participatif ?\nA. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de budget participatif ?"},{"voice":"female","text":"A. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos."}],"audio":"q-05.mp3","audioSeconds":19.11,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un bulletin de participation pour participer à une assemblée citoyenne ?\nA. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un bulletin de participation pour participer à une assemblée citoyenne ?"},{"voice":"female","text":"A. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail."}],"audio":"q-06.mp3","audioSeconds":19.975,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de budget participatif ?\nA. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de budget participatif ?"},{"voice":"female","text":"A. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat."}],"audio":"q-07.mp3","audioSeconds":17.699,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une assemblée citoyenne. Est-ce possible ?\nA. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une assemblée citoyenne. Est-ce possible ?"},{"voice":"female","text":"A. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau."}],"audio":"q-08.mp3","audioSeconds":21.136,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles.","des réunions publiques organisées dans plusieurs quartiers","Une adaptation des tarifs des activités déjà annoncées."],"correct":"C","explanation":"Le document permet de retenir « des réunions publiques organisées dans plusieurs quartiers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la mairie de Strasbourg, à compter de lundi prochain, nous mettons en place des réunions publiques organisées dans plusieurs quartiers. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la mairie de Strasbourg, à compter de lundi prochain, nous mettons en place des réunions publiques organisées dans plusieurs quartiers. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.531,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Un autre créneau est proposé pour un atelier de budget participatif en raison des transports.","La personne arrivera plus tard à un atelier de budget participatif à cause d’une autre obligation.","Le rendez-vous pour un atelier de budget participatif est avancé d’une demi-heure.","Le rendez-vous pour un atelier de budget participatif est reporté au lendemain."],"correct":"B","explanation":"Le document permet de retenir « La personne arrivera plus tard à un atelier de budget participatif à cause d’une autre obligation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de budget participatif ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de budget participatif ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.622,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Remplir le formulaire d’inscription en ligne avant jeudi.","Réserver sa place pour une assemblée citoyenne par téléphone avant jeudi.","Envoyer le formulaire de une assemblée citoyenne par courriel avant vendredi.","Déposer sa demande pour une assemblée citoyenne à l’accueil le jour même."],"correct":"A","explanation":"Le document permet de retenir « Remplir le formulaire d’inscription en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Citoyenneté et politiques publiques » aura lieu dans la mairie de Strasbourg. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Citoyenneté et politiques publiques » aura lieu dans la mairie de Strasbourg. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.967,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Remplir un nouveau formulaire d’inscription pour participer à un atelier de budget participatif.","Demander une confirmation écrite après la fin de un atelier de budget participatif.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier de budget participatif.","Présenter le message de confirmation pour un atelier de budget participatif à l’accueil."],"correct":"D","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier de budget participatif à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de budget participatif, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de budget participatif, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.744,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de budget participatif change de salle mais garde le même horaire.","La séance de un atelier de budget participatif commence une heure plus tôt que prévu.","La séance prévue pour un atelier de budget participatif commence une heure plus tard.","La séance de un atelier de budget participatif est reportée au lendemain à la même heure."],"correct":"C","explanation":"Le document permet de retenir « La séance prévue pour un atelier de budget participatif commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de budget participatif. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de budget participatif. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.97,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Maintenir un atelier de budget participatif avec une démonstration réalisée sans le matériel.","Conserver un atelier de budget participatif et envoyer ensuite la démonstration manquante.","Reporter un atelier de budget participatif jusqu’à ce que le matériel soit disponible.","Garder un atelier de budget participatif mais renoncer à fournir la démonstration prévue."],"correct":"B","explanation":"Le document permet de retenir « Conserver un atelier de budget participatif et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de budget participatif n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de budget participatif n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.647,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans la mairie de Strasbourg, les difficultés ont été réglées avant le lancement.","Dans la mairie de Strasbourg, l’initiative est désormais réservée aux habitués.","Dans la mairie de Strasbourg, la mesure a été suspendue faute de participants."],"correct":"A","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la mairie de Strasbourg : des réunions publiques organisées dans plusieurs quartiers. Le dispositif vise à répondre à une difficulté bien connue : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Plusieurs représentants soulignent toutefois que la première réunion coïncide avec les horaires de travail de nombreux habitants. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la mairie de Strasbourg : des réunions publiques organisées dans plusieurs quartiers. Le dispositif vise à répondre à une difficulté bien connue : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Plusieurs représentants soulignent toutefois que la première réunion coïncide avec les horaires de travail de nombreux habitants. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.237,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Répartir les permanences de la consultation publique sur les espaces verts entre deux lieux différents.","Avancer les horaires de la consultation publique sur les espaces verts en supprimant le relais du soir.","Réserver les permanences de la consultation publique sur les espaces verts aux inscriptions du matin.","Répartir les permanences de la consultation publique sur les espaces verts pour maintenir l’accueil continu."],"correct":"D","explanation":"Le document permet de retenir « Répartir les permanences de la consultation publique sur les espaces verts pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la consultation publique sur les espaces verts.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la consultation publique sur les espaces verts."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.109,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les visiteurs ayant déjà terminé leurs démarches dans la mairie de Strasbourg.","Les personnes qui fréquentent régulièrement les ateliers de la mairie de Strasbourg.","Les visiteurs de la mairie de Strasbourg qui peinent à accéder au service ordinaire.","Les employés chargés d’accueillir et d’orienter les visiteurs de la mairie de Strasbourg."],"correct":"C","explanation":"Le document permet de retenir « Les visiteurs de la mairie de Strasbourg qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la mairie de Strasbourg. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la mairie de Strasbourg. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.412,"slotSeconds":46},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle souhaite déplacer une assemblée citoyenne à cause d’un changement de salle.","Elle travaille encore vendredi à seize heures, au moment d’une assemblée citoyenne.","Elle demande un autre horaire pour une assemblée citoyenne afin d’accompagner un proche.","Elle ne peut se rendre à une assemblée citoyenne à cause d’un retard de transport."],"correct":"B","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une assemblée citoyenne ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une assemblée citoyenne. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une assemblée citoyenne. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.624,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Permettre à chaque participant de poser ses questions et d’échanger.","Répartir les participants de une assemblée citoyenne selon leur expérience.","Réduire le groupe de une assemblée citoyenne pour utiliser moins de matériel.","Adapter le nombre de places de une assemblée citoyenne à la taille de la salle."],"correct":"A","explanation":"Le document permet de retenir « Permettre à chaque participant de poser ses questions et d’échanger ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une assemblée citoyenne, des visites en petits groupes seront proposées dans la mairie de Strasbourg. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une assemblée citoyenne, des visites en petits groupes seront proposées dans la mairie de Strasbourg. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":23.284,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","La visiteuse souhaite des précisions sur la représentativité des personnes consultées."],"correct":"D","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la représentativité des personnes consultées ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la représentativité des personnes consultées. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la représentativité des personnes consultées. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.695,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Prévoir le matériel nécessaire selon les inscriptions à une assemblée citoyenne.","Définir les activités prioritaires selon le public attendu pour une assemblée citoyenne.","Répartir les bénévoles d’une assemblée citoyenne selon les créneaux où ils sont libres.","Adapter les tâches des bénévoles aux compétences requises pour une assemblée citoyenne."],"correct":"C","explanation":"Le document permet de retenir « Répartir les bénévoles d’une assemblée citoyenne selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la mairie de Strasbourg, pour préparer une assemblée citoyenne, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la mairie de Strasbourg, pour préparer une assemblée citoyenne, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":37.053,"slotSeconds":54},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["La meilleure organisation des activités obtenue grâce à un atelier de budget participatif.","Les relations de confiance établies pendant un atelier de budget participatif avec les participants.","Les connaissances pratiques acquises au cours de un atelier de budget participatif.","Les nouveaux contacts professionnels pris pendant un atelier de budget participatif."],"correct":"B","explanation":"Le document permet de retenir « Les relations de confiance établies pendant un atelier de budget participatif avec les participants ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de budget participatif. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de budget participatif. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":46.058,"slotSeconds":63},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Tester des consultations multiples et des comptes rendus accessibles, consulter les usagers puis publier un bilan.","Mettre en place des consultations multiples et des comptes rendus accessibles partout avant de mesurer les résultats.","Consulter les habitants sur des consultations multiples et des comptes rendus accessibles sans mener d’essai concret.","Expérimenter des consultations multiples et des comptes rendus accessibles mais ne publier aucun retour des participants."],"correct":"A","explanation":"Le document permet de retenir « Tester des consultations multiples et des comptes rendus accessibles, consulter les usagers puis publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Citoyenneté et politiques publiques ».\nNous avons discuté de des consultations multiples et des comptes rendus accessibles, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan.\nLes usagers craignent surtout la représentativité des personnes consultées. Une application immédiate, sans consultation, risquerait de perdre leur confiance.\nAlors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Citoyenneté et politiques publiques »."},{"voice":"male","text":"Nous avons discuté de des consultations multiples et des comptes rendus accessibles, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan."},{"voice":"female","text":"Les usagers craignent surtout la représentativité des personnes consultées. Une application immédiate, sans consultation, risquerait de perdre leur confiance."},{"voice":"male","text":"Alors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":57.352,"slotSeconds":74},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de la consultation publique sur les espaces verts comprend surtout des personnes en attente.","L’étude de la consultation publique sur les espaces verts s’appuie principalement sur les réponses des agents.","L’étude de la consultation publique sur les espaces verts donne peu de place aux nouveaux inscrits.","L’étude sur la consultation publique sur les espaces verts n’a presque pas touché ceux qui ont abandonné."],"correct":"D","explanation":"Le document permet de retenir « L’étude sur la consultation publique sur les espaces verts n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant la consultation publique sur les espaces verts. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant la consultation publique sur les espaces verts. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.389,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quel risque fragilise la consultation des habitants ?","options":["Les comptes rendus prévus empêchent de consulter de nouveaux participants.","Les réunions sont organisées uniquement pour les responsables municipaux.","Les horaires de réunion peuvent écarter une partie des habitants concernés.","Les organisateurs envisagent de supprimer toute évaluation des décisions."],"correct":"C","explanation":"Le reportage indique que la première réunion coïncide avec les horaires de travail de nombreux habitants, ce qui menace la représentativité des personnes consultées. Les autres propositions ne sont pas étayées.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la mairie de Strasbourg, une initiative propose des consultations multiples et des comptes rendus accessibles. Les responsables espèrent ainsi répondre à une difficulté bien connue : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées.\nNous soutenons l’objectif général, mais il faut prendre en compte la représentativité des personnes consultées. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils promettent de rendre compte des décisions et d’en évaluer les effets réels. Pourtant, la première réunion coïncide avec les horaires de travail de nombreux habitants. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuel risque fragilise la consultation des habitants ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la mairie de Strasbourg, une initiative propose des consultations multiples et des comptes rendus accessibles. Les responsables espèrent ainsi répondre à une difficulté bien connue : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la représentativité des personnes consultées. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils promettent de rendre compte des décisions et d’en évaluer les effets réels. Pourtant, la première réunion coïncide avec les horaires de travail de nombreux habitants. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quel risque fragilise la consultation des habitants ?"}],"slotSeconds":73,"audio":"q-25.mp3","audioSeconds":53.606},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Le projet de des réunions publiques organisées dans plusieurs quartiers est annoncé mais n’a pas encore été lancé.","La nouvelle mesure, des réunions publiques organisées dans plusieurs quartiers, doit encore être évaluée sur la durée.","Les résultats de des réunions publiques organisées dans plusieurs quartiers concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre des réunions publiques organisées dans plusieurs quartiers dès la fin des premiers essais."],"correct":"B","explanation":"Le document permet de retenir « La nouvelle mesure, des réunions publiques organisées dans plusieurs quartiers, doit encore être évaluée sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé des réunions publiques organisées dans plusieurs quartiers. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. La première réunion coïncide avec les horaires de travail de nombreux habitants. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la prise en compte effective des propositions retenues. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé des réunions publiques organisées dans plusieurs quartiers. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. La première réunion coïncide avec les horaires de travail de nombreux habitants. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la prise en compte effective des propositions retenues. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":49.523,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Adapter les horaires de la consultation publique sur les espaces verts sans pénaliser les usagers du soir.","Conserver les horaires de la consultation publique sur les espaces verts malgré les demandes du matin.","Réserver les créneaux matinaux de la consultation publique sur les espaces verts aux seuls abonnés.","Ouvrir la consultation publique sur les espaces verts plus tôt en supprimant les créneaux tardifs."],"correct":"A","explanation":"Le document permet de retenir « Adapter les horaires de la consultation publique sur les espaces verts sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que la consultation publique sur les espaces verts ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que la consultation publique sur les espaces verts ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.48,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Tester un portail de participation citoyenne sur un seul site avant de l’ouvrir à tous.","Préparer le budget de un portail de participation citoyenne avant de calculer son entretien.","Adapter les équipements de un portail de participation citoyenne après consultation des équipes.","Concevoir un portail de participation citoyenne avant de comprendre les besoins réels des utilisateurs."],"correct":"D","explanation":"Le document permet de retenir « Concevoir un portail de participation citoyenne avant de comprendre les besoins réels des utilisateurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un portail de participation citoyenne a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la représentativité des personnes consultées est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un portail de participation citoyenne a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la représentativité des personnes consultées est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.784,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut comparer les coûts de la prise en compte effective des propositions retenues ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut mesurer la prise en compte effective des propositions retenues ; l’autre demande des récits.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres."],"correct":"C","explanation":"Le document permet de retenir « L’un veut mesurer la prise en compte effective des propositions retenues ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Citoyenneté et politiques publiques ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la prise en compte effective des propositions retenues et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Citoyenneté et politiques publiques »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la prise en compte effective des propositions retenues et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":51.464,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Conserver le bâtiment de un atelier de budget participatif uniquement pour ses activités passées.","Conserver l’identité du lieu accueillant un atelier de budget participatif tout en permettant de nouveaux usages.","Moderniser les salles de un atelier de budget participatif en effaçant les anciennes traces.","Rénover le lieu de un atelier de budget participatif sans changer l’usage actuel des espaces."],"correct":"B","explanation":"Le document permet de retenir « Conserver l’identité du lieu accueillant un atelier de budget participatif tout en permettant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de budget participatif, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de budget participatif, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.688,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Confronter les prévisions d’un modèle aux observations réelles.","Réviser les hypothèses avant toute observation de terrain.","Comparer les prévisions de plusieurs modèles entre elles.","Vérifier seulement si le modèle retrouve les données de départ."],"correct":"A","explanation":"Le document permet de retenir « Confronter les prévisions d’un modèle aux observations réelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la prise en compte effective des propositions retenues. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la prise en compte effective des propositions retenues. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":56.941,"slotSeconds":73},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour la consultation publique sur les espaces verts, annoncer une moyenne sans préciser les hypothèses retenues.","Pour la consultation publique sur les espaces verts, accorder la même fiabilité à toutes les prévisions disponibles.","Pour la consultation publique sur les espaces verts, publier un chiffre précis sans détailler ses limites.","Pour la consultation publique sur les espaces verts, présenter les hypothèses et les incertitudes des prévisions."],"correct":"D","explanation":"Le document permet de retenir « Pour la consultation publique sur les espaces verts, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant la consultation publique sur les espaces verts, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant la consultation publique sur les espaces verts, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":53.07,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Les chiffres de la mairie de Strasbourg ne tiennent pas compte du prix des activités.","La hausse des visites à la mairie de Strasbourg vient surtout des horaires étendus.","La hausse des visites ne démontre pas un bénéfice durable du projet.","La fréquentation de la mairie de Strasbourg varie trop selon les saisons."],"correct":"C","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la mairie de Strasbourg, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : des réunions publiques organisées dans plusieurs quartiers. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la prise en compte effective des propositions retenues ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la mairie de Strasbourg, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : des réunions publiques organisées dans plusieurs quartiers. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la prise en compte effective des propositions retenues ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.083,"slotSeconds":65},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Évaluer la consultation publique sur les espaces verts auprès de tous puis supprimer l’accueil individuel.","Faire tester la consultation publique sur les espaces verts par différents publics et maintenir une aide humaine.","Faire tester la consultation publique sur les espaces verts uniquement par les usagers réguliers.","Maintenir une aide humaine à la consultation publique sur les espaces verts pendant le seul lancement."],"correct":"B","explanation":"Le document permet de retenir « Faire tester la consultation publique sur les espaces verts par différents publics et maintenir une aide humaine ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la mairie de Strasbourg.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la représentativité des personnes consultées.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la mairie de Strasbourg."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la représentativité des personnes consultées."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.209,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les résultats techniques de la salle du conseil municipal suffiraient même si les usages réels diffèrent.","La performance du dispositif de la salle du conseil municipal exige un entretien régulier.","Les usages quotidiens du matériel de la salle du conseil municipal peuvent changer ses effets.","Les conditions de terrain de la salle du conseil municipal influencent les résultats observés."],"correct":"A","explanation":"Le document permet de retenir « Les résultats techniques de la salle du conseil municipal suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la salle du conseil municipal affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la salle du conseil municipal affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.446,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Répartir les rôles de un atelier de budget participatif entre des participants désignés à l’avance.","Évaluer le lien créé à un atelier de budget participatif uniquement par le nombre de présences.","Assurer une présence régulière aux séances de un atelier de budget participatif sans échanger.","Permettre une participation volontaire et réciproque à un atelier de budget participatif."],"correct":"D","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de budget participatif ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de budget participatif réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la représentativité des personnes consultées. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de budget participatif réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la représentativité des personnes consultées. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":53.668,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits de la consultation publique sur les espaces verts sans consulter les archives disponibles.","Conserver les récits de la consultation publique sur les espaces verts qui concordent avec la majorité.","Comparer les récits concernant la consultation publique sur les espaces verts aux faits vérifiables.","Classer les témoignages de la consultation publique sur les espaces verts selon l’ancienneté de leurs auteurs."],"correct":"C","explanation":"Le document permet de retenir « Comparer les récits concernant la consultation publique sur les espaces verts aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant la consultation publique sur les espaces verts, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant la consultation publique sur les espaces verts, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":54.132,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès de des réunions publiques organisées dans plusieurs quartiers réduit les demandes des services voisins.","Une initiative comme des réunions publiques organisées dans plusieurs quartiers peut devenir victime de son succès et fragiliser les usagers.","La fréquentation de des réunions publiques organisées dans plusieurs quartiers ralentit la promotion du dispositif.","La croissance de des réunions publiques organisées dans plusieurs quartiers augmente le budget sans effet sur les usagers."],"correct":"B","explanation":"Le document permet de retenir « Une initiative comme des réunions publiques organisées dans plusieurs quartiers peut devenir victime de son succès et fragiliser les usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Citoyenneté et politiques publiques ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, des réunions publiques organisées dans plusieurs quartiers peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la représentativité des personnes consultées. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Citoyenneté et politiques publiques ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, des réunions publiques organisées dans plusieurs quartiers peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les habitants disponibles en soirée ne représentent pas toutes les personnes concernées. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la représentativité des personnes consultées. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.826,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Stabiliser les moyens et suivre la prise en compte effective des propositions retenues dans la durée.","Obtenir des moyens durables mais ne plus mesurer la prise en compte effective des propositions retenues.","Étendre le service en privilégiant seulement les premiers résultats de la prise en compte effective des propositions retenues.","Suivre la prise en compte effective des propositions retenues en comptant sur les bénévoles actuels."],"correct":"A","explanation":"Le document permet de retenir « Stabiliser les moyens et suivre la prise en compte effective des propositions retenues dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à la consultation publique sur les espaces verts, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper la première réunion coïncide avec les horaires de travail de nombreux habitants. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la prise en compte effective des propositions retenues. L’idée n’est pas d’abandonner l’ambition de départ : rendre compte des décisions et évaluer leurs effets réels. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à la consultation publique sur les espaces verts, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper la première réunion coïncide avec les horaires de travail de nombreux habitants. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la prise en compte effective des propositions retenues. L’idée n’est pas d’abandonner l’ambition de départ : rendre compte des décisions et évaluer leurs effets réels. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":65.622,"slotSeconds":83}]},{"id":"tcf-listening-20","version":"tcf-listening-2026-11-test20-v2","title":"TCF Listening · Test 20","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La scène représente une personne assise, occupée à consulter un dossier de mobilité.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un dossier de mobilité à une table.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un dossier de mobilité à une table."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.804,"slotSeconds":32},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Un homme présente une affiche liée à échanges internationaux.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur échanges internationaux à un groupe. D. Il prépare un repas dans la cuisine.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur échanges internationaux à un groupe. D. Il prépare un repas dans la cuisine."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.328,"slotSeconds":32},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Deux interlocuteurs préparent une semaine des cultures francophones autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Trois personnes font de la randonnée. B. Deux personnes préparent une semaine des cultures francophones autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Trois personnes font de la randonnée. B. Deux personnes préparent une semaine des cultures francophones autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.871,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'illustration montre une personne portant un sac devant le centre d'échanges de Lyon.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme porte un sac devant le centre d'échanges de Lyon. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme porte un sac devant le centre d'échanges de Lyon. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.617,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de conversation multilingue ?\nA. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de conversation multilingue ?"},{"voice":"female","text":"A. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil."}],"audio":"q-05.mp3","audioSeconds":19.594,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un dossier de mobilité pour participer à une semaine des cultures francophones ?\nA. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un dossier de mobilité pour participer à une semaine des cultures francophones ?"},{"voice":"female","text":"A. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche."}],"audio":"q-06.mp3","audioSeconds":20.358,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de conversation multilingue ?\nA. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de conversation multilingue ?"},{"voice":"female","text":"A. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr."}],"audio":"q-07.mp3","audioSeconds":17.578,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une semaine des cultures francophones. Est-ce possible ?\nA. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une semaine des cultures francophones. Est-ce possible ?"},{"voice":"female","text":"A. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue."}],"audio":"q-08.mp3","audioSeconds":21.775,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","une permanence de traduction pour les nouveaux arrivants"],"correct":"D","explanation":"Le document permet de retenir « une permanence de traduction pour les nouveaux arrivants ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans le centre d'échanges de Lyon, à compter de lundi prochain, nous mettons en place une permanence de traduction pour les nouveaux arrivants. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans le centre d'échanges de Lyon, à compter de lundi prochain, nous mettons en place une permanence de traduction pour les nouveaux arrivants. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.74,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier de conversation multilingue est avancé d’une demi-heure.","Le rendez-vous pour un atelier de conversation multilingue est reporté au lendemain.","Le rendez-vous d’un atelier de conversation multilingue est repoussé à cause d’une réunion prolongée.","Un autre créneau est proposé pour un atelier de conversation multilingue en raison des transports."],"correct":"C","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de conversation multilingue est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de conversation multilingue ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de conversation multilingue ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.704,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Envoyer le formulaire de une semaine des cultures francophones par courriel avant vendredi.","Remplir en ligne le formulaire d’inscription pour une semaine des cultures francophones avant jeudi.","Déposer sa demande pour une semaine des cultures francophones à l’accueil le jour même.","Réserver sa place pour une semaine des cultures francophones par téléphone avant jeudi."],"correct":"B","explanation":"Le document permet de retenir « Remplir en ligne le formulaire d’inscription pour une semaine des cultures francophones avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Échanges internationaux » aura lieu dans le centre d'échanges de Lyon. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Échanges internationaux » aura lieu dans le centre d'échanges de Lyon. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":23.621,"slotSeconds":39},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Montrer le courriel de confirmation à l’accueil pour retrouver son inscription.","Demander une confirmation écrite après la fin de un atelier de conversation multilingue.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier de conversation multilingue.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de conversation multilingue."],"correct":"A","explanation":"Le document permet de retenir « Montrer le courriel de confirmation à l’accueil pour retrouver son inscription ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de conversation multilingue, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de conversation multilingue, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.21,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de conversation multilingue commence une heure plus tôt que prévu.","La séance de un atelier de conversation multilingue est reportée au lendemain à la même heure.","La séance de un atelier de conversation multilingue change de salle mais garde le même horaire.","La séance prévue pour un atelier de conversation multilingue commence une heure plus tard."],"correct":"D","explanation":"Le document permet de retenir « La séance prévue pour un atelier de conversation multilingue commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de conversation multilingue. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de conversation multilingue. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.597,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Reporter un atelier de conversation multilingue jusqu’à ce que le matériel soit disponible.","Garder un atelier de conversation multilingue mais renoncer à fournir la démonstration prévue.","Conserver un atelier de conversation multilingue et envoyer ensuite la démonstration manquante.","Maintenir un atelier de conversation multilingue avec une démonstration réalisée sans le matériel."],"correct":"C","explanation":"Le document permet de retenir « Conserver un atelier de conversation multilingue et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de conversation multilingue n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de conversation multilingue n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.856,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans le centre d'échanges de Lyon, l’initiative est désormais réservée aux habitués.","La mesure présentée à le centre d'échanges de Lyon répond au besoin sans lever toutes les difficultés.","Dans le centre d'échanges de Lyon, la mesure a été suspendue faute de participants.","Dans le centre d'échanges de Lyon, les difficultés ont été réglées avant le lancement."],"correct":"B","explanation":"Le document permet de retenir « La mesure présentée à le centre d'échanges de Lyon répond au besoin sans lever toutes les difficultés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre d'échanges de Lyon : une permanence de traduction pour les nouveaux arrivants. Le dispositif vise à répondre à une difficulté bien connue : les démarches administratives diffèrent selon les pays et créent des malentendus. Plusieurs représentants soulignent toutefois que les rendez-vous de rentrée sont saturés à certaines heures. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre d'échanges de Lyon : une permanence de traduction pour les nouveaux arrivants. Le dispositif vise à répondre à une difficulté bien connue : les démarches administratives diffèrent selon les pays et créent des malentendus. Plusieurs représentants soulignent toutefois que les rendez-vous de rentrée sont saturés à certaines heures. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.688,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Répartir les permanences du programme d'accueil des étudiants étrangers pour maintenir l’accueil continu.","Avancer les horaires de le programme d'accueil des étudiants étrangers en supprimant le relais du soir.","Réserver les permanences de le programme d'accueil des étudiants étrangers aux inscriptions du matin.","Répartir les permanences de le programme d'accueil des étudiants étrangers entre deux lieux différents."],"correct":"A","explanation":"Le document permet de retenir « Répartir les permanences du programme d'accueil des étudiants étrangers pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme d'accueil des étudiants étrangers.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme d'accueil des étudiants étrangers."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.62,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui fréquentent régulièrement les ateliers de le centre d'échanges de Lyon.","Les employés chargés d’accueillir et d’orienter les visiteurs de le centre d'échanges de Lyon.","Les visiteurs ayant déjà terminé leurs démarches dans le centre d'échanges de Lyon.","Les visiteurs du centre d'échanges de Lyon qui peinent à accéder au service ordinaire."],"correct":"D","explanation":"Le document permet de retenir « Les visiteurs du centre d'échanges de Lyon qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans le centre d'échanges de Lyon. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les démarches administratives diffèrent selon les pays et créent des malentendus. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans le centre d'échanges de Lyon. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les démarches administratives diffèrent selon les pays et créent des malentendus. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":31.376,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle demande un autre horaire pour une semaine des cultures francophones afin d’accompagner un proche.","Elle ne peut se rendre à une semaine des cultures francophones à cause d’un retard de transport.","Elle travaille encore vendredi à seize heures, au moment d’une semaine des cultures francophones.","Elle souhaite déplacer une semaine des cultures francophones à cause d’un changement de salle."],"correct":"C","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une semaine des cultures francophones ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une semaine des cultures francophones. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une semaine des cultures francophones. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.78,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Réduire le groupe de une semaine des cultures francophones pour utiliser moins de matériel.","Limiter le groupe pendant une semaine des cultures francophones afin que chacun puisse poser des questions.","Adapter le nombre de places de une semaine des cultures francophones à la taille de la salle.","Répartir les participants de une semaine des cultures francophones selon leur expérience."],"correct":"B","explanation":"Le document permet de retenir « Limiter le groupe pendant une semaine des cultures francophones afin que chacun puisse poser des questions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une semaine des cultures francophones, des visites en petits groupes seront proposées dans le centre d'échanges de Lyon. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une semaine des cultures francophones, des visites en petits groupes seront proposées dans le centre d'échanges de Lyon. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.515,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["La visiteuse souhaite des précisions sur le respect des expériences et des habitudes culturelles.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet."],"correct":"A","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur le respect des expériences et des habitudes culturelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte le respect des expériences et des habitudes culturelles. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte le respect des expériences et des habitudes culturelles. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.252,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Définir les activités prioritaires selon le public attendu pour une semaine des cultures francophones.","Adapter les tâches des bénévoles aux compétences requises pour une semaine des cultures francophones.","Prévoir le matériel nécessaire selon les inscriptions à une semaine des cultures francophones.","Répartir les bénévoles d’une semaine des cultures francophones selon les créneaux où ils sont libres."],"correct":"D","explanation":"Le document permet de retenir « Répartir les bénévoles d’une semaine des cultures francophones selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans le centre d'échanges de Lyon, pour préparer une semaine des cultures francophones, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans le centre d'échanges de Lyon, pour préparer une semaine des cultures francophones, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.705,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les connaissances pratiques acquises au cours de un atelier de conversation multilingue.","Les nouveaux contacts professionnels pris pendant un atelier de conversation multilingue.","Les relations de confiance créées autour d’un atelier de conversation multilingue.","La meilleure organisation des activités obtenue grâce à un atelier de conversation multilingue."],"correct":"C","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de conversation multilingue ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de conversation multilingue. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les démarches administratives diffèrent selon les pays et créent des malentendus. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de conversation multilingue. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les démarches administratives diffèrent selon les pays et créent des malentendus. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":47.232,"slotSeconds":64},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Consulter les habitants sur un accompagnement multilingue et des interlocuteurs identifiés sans mener d’essai concret.","Expérimenter un accompagnement multilingue et des interlocuteurs identifiés, recueillir les avis et publier un bilan.","Expérimenter un accompagnement multilingue et des interlocuteurs identifiés mais ne publier aucun retour des participants.","Mettre en place un accompagnement multilingue et des interlocuteurs identifiés partout avant de mesurer les résultats."],"correct":"B","explanation":"Le document permet de retenir « Expérimenter un accompagnement multilingue et des interlocuteurs identifiés, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Échanges internationaux ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré un accompagnement multilingue et des interlocuteurs identifiés.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les démarches administratives diffèrent selon les pays et créent des malentendus.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Échanges internationaux »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré un accompagnement multilingue et des interlocuteurs identifiés."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les démarches administratives diffèrent selon les pays et créent des malentendus."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":54.38,"slotSeconds":71},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les usagers qui ont abandonné le programme d'accueil des étudiants étrangers sont peu représentés.","L’étude de le programme d'accueil des étudiants étrangers s’appuie principalement sur les réponses des agents.","L’étude de le programme d'accueil des étudiants étrangers donne peu de place aux nouveaux inscrits.","L’étude de le programme d'accueil des étudiants étrangers comprend surtout des personnes en attente."],"correct":"A","explanation":"Le document permet de retenir « Les usagers qui ont abandonné le programme d'accueil des étudiants étrangers sont peu représentés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le programme d'accueil des étudiants étrangers. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les démarches administratives diffèrent selon les pays et créent des malentendus. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le programme d'accueil des étudiants étrangers. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les démarches administratives diffèrent selon les pays et créent des malentendus. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":54.098,"slotSeconds":71},{"number":25,"kind":"television-report","question":"Quel défi reste à résoudre pour ce dispositif d’accueil ?","options":["Remplacer l’accompagnement multilingue par une information écrite commune.","Réduire le nombre de rendez-vous pour éviter les demandes internationales.","Réserver le suivi de longue durée aux personnes déjà accompagnées.","Assurer un suivi durable malgré les périodes de saturation des rendez-vous."],"correct":"D","explanation":"Le reportage présente un accompagnement multilingue et un suivi au-delà des premiers mois, tandis que les créneaux de rentrée sont déjà saturés. Les autres propositions imposent des restrictions ou des changements de service qui ne sont pas annoncés.","transcript":"Question 25.\nVous regardez un reportage régional. Dans le centre d'échanges de Lyon, une initiative propose un accompagnement multilingue et des interlocuteurs identifiés. Les responsables espèrent ainsi répondre à une difficulté bien connue : les démarches administratives diffèrent selon les pays et créent des malentendus.\nNous soutenons l’objectif général, mais il faut prendre en compte le respect des expériences et des habitudes culturelles. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment vouloir assurer la continuité du suivi au-delà des premiers mois. Pourtant, les rendez-vous de rentrée sont saturés à certaines heures. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuel défi reste à résoudre pour ce dispositif d’accueil ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans le centre d'échanges de Lyon, une initiative propose un accompagnement multilingue et des interlocuteurs identifiés. Les responsables espèrent ainsi répondre à une difficulté bien connue : les démarches administratives diffèrent selon les pays et créent des malentendus."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte le respect des expériences et des habitudes culturelles. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment vouloir assurer la continuité du suivi au-delà des premiers mois. Pourtant, les rendez-vous de rentrée sont saturés à certaines heures. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quel défi reste à résoudre pour ce dispositif d’accueil ?"}],"slotSeconds":72,"audio":"q-25.mp3","audioSeconds":53.989},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les résultats de une permanence de traduction pour les nouveaux arrivants concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre une permanence de traduction pour les nouveaux arrivants dès la fin des premiers essais.","Les premiers effets d’une permanence de traduction pour les nouveaux arrivants doivent être vérifiés dans la durée.","Le projet de une permanence de traduction pour les nouveaux arrivants est annoncé mais n’a pas encore été lancé."],"correct":"C","explanation":"Le document permet de retenir « Les premiers effets d’une permanence de traduction pour les nouveaux arrivants doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une permanence de traduction pour les nouveaux arrivants. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les rendez-vous de rentrée sont saturés à certaines heures. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la capacité des participants à accomplir leurs démarches sans assistance répétée. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une permanence de traduction pour les nouveaux arrivants. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les rendez-vous de rentrée sont saturés à certaines heures. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la capacité des participants à accomplir leurs démarches sans assistance répétée. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":50.144,"slotSeconds":67},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Réserver les créneaux matinaux de le programme d'accueil des étudiants étrangers aux seuls abonnés.","Réorganiser les horaires du programme d'accueil des étudiants étrangers sans supprimer les créneaux du soir.","Ouvrir le programme d'accueil des étudiants étrangers plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de le programme d'accueil des étudiants étrangers malgré les demandes du matin."],"correct":"B","explanation":"Le document permet de retenir « Réorganiser les horaires du programme d'accueil des étudiants étrangers sans supprimer les créneaux du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le programme d'accueil des étudiants étrangers ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le programme d'accueil des étudiants étrangers ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":42.374,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Préparer le budget de un espace d'accueil plurilingue avant de calculer son entretien.","Adapter les équipements de un espace d'accueil plurilingue après consultation des équipes.","Tester un espace d'accueil plurilingue sur un seul site avant de l’ouvrir à tous."],"correct":"A","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un espace d'accueil plurilingue a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le respect des expériences et des habitudes culturelles est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un espace d'accueil plurilingue a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le respect des expériences et des habitudes culturelles est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":50.086,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de la capacité des participants à accomplir leurs démarches sans assistance répétée ; l’autre mesure la fréquentation.","L’un veut mesurer la capacité des participants à accomplir leurs démarches sans assistance répétée ; l’autre demande des récits."],"correct":"D","explanation":"Le document permet de retenir « L’un veut mesurer la capacité des participants à accomplir leurs démarches sans assistance répétée ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Échanges internationaux ».\nSans chiffres comparables, impossible de dire si une permanence de traduction pour les nouveaux arrivants apporte un bénéfice mesurable. Nous devons étudier la capacité des participants à accomplir leurs démarches sans assistance répétée.\nLes chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les démarches administratives diffèrent selon les pays et créent des malentendus.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Échanges internationaux »."},{"voice":"male","text":"Sans chiffres comparables, impossible de dire si une permanence de traduction pour les nouveaux arrivants apporte un bénéfice mesurable. Nous devons étudier la capacité des participants à accomplir leurs démarches sans assistance répétée."},{"voice":"female","text":"Les chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les démarches administratives diffèrent selon les pays et créent des malentendus."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":49.086,"slotSeconds":66},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Moderniser les salles de un atelier de conversation multilingue en effaçant les anciennes traces.","Rénover le lieu de un atelier de conversation multilingue sans changer l’usage actuel des espaces.","Préserver l’histoire du lieu d’un atelier de conversation multilingue tout en y proposant de nouveaux usages.","Conserver le bâtiment de un atelier de conversation multilingue uniquement pour ses activités passées."],"correct":"C","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de conversation multilingue tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de conversation multilingue, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de conversation multilingue, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.648,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Comparer la force d’une corrélation dans plusieurs échantillons.","Ne pas confondre une corrélation statistique et une cause démontrée.","Déduire un effet causal lorsque deux tendances se répètent.","Établir une cause unique à partir de deux changements simultanés."],"correct":"B","explanation":"Le document permet de retenir « Ne pas confondre une corrélation statistique et une cause démontrée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la capacité des participants à accomplir leurs démarches sans assistance répétée. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les démarches administratives diffèrent selon les pays et créent des malentendus. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la capacité des participants à accomplir leurs démarches sans assistance répétée. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les démarches administratives diffèrent selon les pays et créent des malentendus. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":52.808,"slotSeconds":69},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le programme d'accueil des étudiants étrangers, présenter les hypothèses et les incertitudes des prévisions.","Pour le programme d'accueil des étudiants étrangers, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le programme d'accueil des étudiants étrangers, publier un chiffre précis sans détailler ses limites.","Pour le programme d'accueil des étudiants étrangers, annoncer une moyenne sans préciser les hypothèses retenues."],"correct":"A","explanation":"Le document permet de retenir « Pour le programme d'accueil des étudiants étrangers, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le programme d'accueil des étudiants étrangers, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le programme d'accueil des étudiants étrangers, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.101,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites à le centre d'échanges de Lyon vient surtout des horaires étendus.","La fréquentation de le centre d'échanges de Lyon varie trop selon les saisons.","Les chiffres de le centre d'échanges de Lyon ne tiennent pas compte du prix des activités.","La hausse des visites ne démontre pas un bénéfice durable du projet."],"correct":"D","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans le centre d'échanges de Lyon, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une permanence de traduction pour les nouveaux arrivants. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la capacité des participants à accomplir leurs démarches sans assistance répétée ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans le centre d'échanges de Lyon, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une permanence de traduction pour les nouveaux arrivants. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la capacité des participants à accomplir leurs démarches sans assistance répétée ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":49.964,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester le programme d'accueil des étudiants étrangers uniquement par les usagers réguliers.","Maintenir une aide humaine à le programme d'accueil des étudiants étrangers pendant le seul lancement.","Faire tester le programme d'accueil des étudiants étrangers par divers publics, avec une aide humaine conservée.","Évaluer le programme d'accueil des étudiants étrangers auprès de tous puis supprimer l’accueil individuel."],"correct":"C","explanation":"Le document permet de retenir « Faire tester le programme d'accueil des étudiants étrangers par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans le centre d'échanges de Lyon.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le respect des expériences et des habitudes culturelles.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans le centre d'échanges de Lyon."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le respect des expériences et des habitudes culturelles."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":54.102,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les usages quotidiens du matériel de la maison internationale peuvent changer ses effets.","Une technologie installée dans la maison internationale garantit un bon résultat sans tenir compte des usages.","Les conditions de terrain de la maison internationale influencent les résultats observés.","La performance du dispositif de la maison internationale exige un entretien régulier."],"correct":"B","explanation":"Le document permet de retenir « Une technologie installée dans la maison internationale garantit un bon résultat sans tenir compte des usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la maison internationale affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la maison internationale affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.673,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Permettre une participation volontaire et réciproque à un atelier de conversation multilingue.","Évaluer le lien créé à un atelier de conversation multilingue uniquement par le nombre de présences.","Assurer une présence régulière aux séances de un atelier de conversation multilingue sans échanger.","Répartir les rôles de un atelier de conversation multilingue entre des participants désignés à l’avance."],"correct":"A","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de conversation multilingue ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de conversation multilingue réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le respect des expériences et des habitudes culturelles. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de conversation multilingue réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le respect des expériences et des habitudes culturelles. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.504,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Conserver les récits de le programme d'accueil des étudiants étrangers qui concordent avec la majorité.","Classer les témoignages de le programme d'accueil des étudiants étrangers selon l’ancienneté de leurs auteurs.","Comparer les récits de le programme d'accueil des étudiants étrangers sans consulter les archives disponibles.","Comparer les récits concernant le programme d'accueil des étudiants étrangers aux faits vérifiables."],"correct":"D","explanation":"Le document permet de retenir « Comparer les récits concernant le programme d'accueil des étudiants étrangers aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le programme d'accueil des étudiants étrangers, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le programme d'accueil des étudiants étrangers, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":54.423,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La fréquentation de une permanence de traduction pour les nouveaux arrivants ralentit la promotion du dispositif.","La croissance de une permanence de traduction pour les nouveaux arrivants augmente le budget sans effet sur les usagers.","Le succès d’une permanence de traduction pour les nouveaux arrivants peut créer des difficultés aux usagers.","Le succès de une permanence de traduction pour les nouveaux arrivants réduit les demandes des services voisins."],"correct":"C","explanation":"Le document permet de retenir « Le succès d’une permanence de traduction pour les nouveaux arrivants peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Échanges internationaux ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une permanence de traduction pour les nouveaux arrivants peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les démarches administratives diffèrent selon les pays et créent des malentendus. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le respect des expériences et des habitudes culturelles. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Échanges internationaux ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une permanence de traduction pour les nouveaux arrivants peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les démarches administratives diffèrent selon les pays et créent des malentendus. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le respect des expériences et des habitudes culturelles. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.768,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Étendre le service en privilégiant seulement les premiers résultats de la capacité des participants à accomplir leurs démarches sans assistance répétée.","Organiser des ressources durables et suivre la capacité des participants à accomplir leurs démarches sans assistance répétée pour poursuivre le programme d'accueil des étudiants étrangers.","Suivre la capacité des participants à accomplir leurs démarches sans assistance répétée en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer la capacité des participants à accomplir leurs démarches sans assistance répétée."],"correct":"B","explanation":"Le document permet de retenir « Organiser des ressources durables et suivre la capacité des participants à accomplir leurs démarches sans assistance répétée pour poursuivre le programme d'accueil des étudiants étrangers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le programme d'accueil des étudiants étrangers, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les rendez-vous de rentrée sont saturés à certaines heures. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la capacité des participants à accomplir leurs démarches sans assistance répétée. L’idée n’est pas d’abandonner l’ambition de départ : assurer la continuité du suivi après les premiers mois. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le programme d'accueil des étudiants étrangers, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les rendez-vous de rentrée sont saturés à certaines heures. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la capacité des participants à accomplir leurs démarches sans assistance répétée. L’idée n’est pas d’abandonner l’ambition de départ : assurer la continuité du suivi après les premiers mois. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":65.975,"slotSeconds":83}]}]$six_data$::jsonb;
 paper jsonb; previous jsonb; existing jsonb;
 protected_before jsonb;protected_after jsonb;
 old_before jsonb;old_after jsonb;
 others_before jsonb;others_after jsonb;
 function_before text;function_after text;
begin
 perform pg_advisory_xact_lock(hashtext('hzad-tcf-listening-15-20-v2'));
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_before;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_before
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test15-v2','tcf-listening-2026-11-test16-v2','tcf-listening-2026-11-test17-v2','tcf-listening-2026-11-test18-v2','tcf-listening-2026-11-test19-v2','tcf-listening-2026-11-test20-v2');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into others_before
  from academy_tcf_listening.published where test_id not in ('tcf-listening-15','tcf-listening-16','tcf-listening-17','tcf-listening-18','tcf-listening-19','tcf-listening-20');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into function_before;
 for paper in select value from jsonb_array_elements(wanted) loop
  select content into previous from academy_tcf_listening.papers
   where id=paper->>'id' and version='tcf-listening-2026-11-test'||right(paper->>'id',2)||'-v1';
  if not found then raise exception 'Historical v1 source bank missing: %',paper->>'id';end if;
  if jsonb_array_length(paper->'questions')<>39 or (paper->>'seconds')::integer<>2100 or
   (select sum((q->>'slotSeconds')::integer) from jsonb_array_elements(paper->'questions') q)<>2100
   or exists(
    select 1 from jsonb_array_elements(paper->'questions') with ordinality x(q,n)
    where (q->>'number')::integer<>x.n or jsonb_array_length(q->'options')<>4
      or q->>'correct' not in ('A','B','C','D')
      or coalesce((q->>'audioSeconds')::numeric,0)<=0
      or (q->>'audioSeconds')::numeric+12>(q->>'slotSeconds')::numeric
   ) then raise exception 'Incomplete or mistimed listening v2 bank: %',paper->>'id';end if;
  if exists(
   select 1 from jsonb_array_elements(paper->'questions') with ordinality new(q,n)
    join jsonb_array_elements(previous->'questions') with ordinality old(q,n) using(n)
    where new.q->>'number' is distinct from old.q->>'number'
     or new.q->>'kind' is distinct from old.q->>'kind'
     or new.q->>'correct' is distinct from old.q->>'correct'
     or (new.n<>25 and new.q->>'question' is distinct from old.q->>'question')
     or (new.n<>25 and new.q->'segments' is distinct from old.q->'segments')
     or (new.n<>25 and new.q->>'transcript' is distinct from old.q->>'transcript')
     or new.q->>'audio' is distinct from old.q->>'audio'
     or (new.n<>25 and new.q->>'audioSeconds' is distinct from old.q->>'audioSeconds')
     or new.q->>'slotSeconds' is distinct from old.q->>'slotSeconds'
     or new.q->>'image' is distinct from old.q->>'image'
     or (new.n<=8 and new.q->'options' is distinct from old.q->'options')
  ) then raise exception 'Audio, key or historical timing changed: %',paper->>'id';end if;
  if (paper->'questions'->24->'segments') is not distinct from (previous->'questions'->24->'segments')
    or (paper->'questions'->24->>'question') is not distinct from (previous->'questions'->24->>'question')
    then raise exception 'Expected corrected Q25 source/recording missing: %',paper->>'id'; end if;
  select content into existing from academy_tcf_listening.papers
   where id=paper->>'id' and version=paper->>'version';
  if found and existing is distinct from paper then
   raise exception 'Refusing to overwrite immutable v2 bank: %',paper->>'id';end if;
  insert into academy_tcf_listening.papers(id,version,content)
   values(paper->>'id',paper->>'version',paper) on conflict(id,version) do nothing;
  insert into academy_tcf_listening.published(test_id,version)
   values(paper->>'id',paper->>'version')
   on conflict(test_id) do update set version=excluded.version
    where academy_tcf_listening.published.version is distinct from excluded.version;
 end loop;
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_after;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_after
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test15-v2','tcf-listening-2026-11-test16-v2','tcf-listening-2026-11-test17-v2','tcf-listening-2026-11-test18-v2','tcf-listening-2026-11-test19-v2','tcf-listening-2026-11-test20-v2');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into others_after
  from academy_tcf_listening.published where test_id not in ('tcf-listening-15','tcf-listening-16','tcf-listening-17','tcf-listening-18','tcf-listening-19','tcf-listening-20');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into function_after;
 if protected_before is distinct from protected_after
 or old_before is distinct from old_after or others_before is distinct from others_after
 or function_before is distinct from function_after
 then raise exception 'Student/history preservation mismatch: entire batch rolled back';end if;
 if exists(
  select 1 from jsonb_array_elements(wanted) p
  where not exists(select 1 from academy_tcf_listening.papers b
   join academy_tcf_listening.published v on v.test_id=b.id and v.version=b.version
   where b.id=p->>'id' and b.version=p->>'version' and b.content=p)
 ) then raise exception 'One or more exact TCF listening v2 bank publications failed';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='academy_tcf_listening' and c.relkind='r' and not c.relrowsecurity)
  or has_table_privilege('anon','academy_tcf_listening.papers','select')
  or has_table_privilege('authenticated','academy_tcf_listening.papers','select')
 then raise exception 'Private answer-key bank protection altered';end if;
end;
$publish_six$;
